-- ===== 0129_kfc_pos.sql =====
/*
 * Kassa (point of sale) for the shop counter.
 *
 * A till session is opened with a cash float and closed with a counted amount;
 * the difference against what the session's cash sales say should be in the
 * drawer is the Z-report. One sale is one call to kfc_pos_sale, which in a
 * single transaction:
 *
 *   - writes a paid sales invoice (shelf prices are incl. VAT; the invoice
 *     stores lines and totals excl. VAT + VAT, like every other invoice),
 *   - books a 'sale' stock move per line through kfc_book_move, linked to the
 *     invoice, taken from the bin that holds the most of that article,
 *   - records the payments (cash / pin / other) against the session,
 *   - and, when a known customer is chosen, settles the ledger entry the
 *     kfc_post_invoice trigger just posted, so their balance stays at zero.
 *
 * Retry-safe: p_key is the client's id for the sale. A second call with the
 * same key returns the invoice already made instead of selling twice.
 *
 * Server-only like the other kfc_* tables: RLS on, no policies, no grants.
 */

create table if not exists public.kfc_pos_sessions (
  id                   uuid primary key default gen_random_uuid(),
  register             text not null default 'winkel',
  opened_at            timestamptz not null default now(),
  opened_by            uuid,
  opening_float_cents  integer not null default 0 check (opening_float_cents >= 0),
  closed_at            timestamptz,
  closed_by            uuid,
  expected_cash_cents  integer,
  counted_cash_cents   integer check (counted_cash_cents is null or counted_cash_cents >= 0),
  note                 text
);

-- One open session per till.
create unique index if not exists kfc_pos_sessions_one_open
  on public.kfc_pos_sessions (register) where closed_at is null;

alter table public.sales_invoices
  add column if not exists pos_session_id uuid references public.kfc_pos_sessions (id),
  add column if not exists pos_key text;

create unique index if not exists sales_invoices_pos_key on public.sales_invoices (pos_key) where pos_key is not null;
create index if not exists sales_invoices_pos_session on public.sales_invoices (pos_session_id) where pos_session_id is not null;

create table if not exists public.kfc_pos_payments (
  id                bigserial primary key,
  session_id        uuid not null references public.kfc_pos_sessions (id),
  sales_invoice_id  uuid not null references public.sales_invoices (id) on delete restrict,
  method            text not null check (method in ('cash', 'pin', 'other')),
  -- What stays in the till / on the terminal: for cash, tendered minus change.
  amount_cents      integer not null check (amount_cents > 0),
  tendered_cents    integer not null check (tendered_cents >= amount_cents),
  created_at        timestamptz not null default now(),
  created_by        uuid,
  idempotency_key   text not null unique
);

create index if not exists kfc_pos_payments_session on public.kfc_pos_payments (session_id);

-- ---------------------------------------------------------------------------
-- Open / close
-- ---------------------------------------------------------------------------

create or replace function public.kfc_pos_open(p_register text, p_float_cents integer, p_opened_by uuid)
returns public.kfc_pos_sessions language plpgsql as $$
declare v_row public.kfc_pos_sessions;
begin
  if p_float_cents is null or p_float_cents < 0 or p_float_cents > 10000000 then raise exception 'KFC_POS_BAD_FLOAT'; end if;
  select * into v_row from public.kfc_pos_sessions where register = p_register and closed_at is null;
  if found then return v_row; end if;
  insert into public.kfc_pos_sessions (register, opening_float_cents, opened_by)
  values (p_register, p_float_cents, p_opened_by)
  returning * into v_row;
  return v_row;
exception when unique_violation then
  select * into v_row from public.kfc_pos_sessions where register = p_register and closed_at is null;
  return v_row;
end $$;

create or replace function public.kfc_pos_close(p_session uuid, p_counted_cents integer, p_note text, p_closed_by uuid)
returns public.kfc_pos_sessions language plpgsql as $$
declare v_row public.kfc_pos_sessions; v_cash integer;
begin
  if p_counted_cents is null or p_counted_cents < 0 or p_counted_cents > 100000000 then raise exception 'KFC_POS_BAD_COUNT'; end if;
  select * into v_row from public.kfc_pos_sessions where id = p_session for update;
  if not found then raise exception 'KFC_POS_NO_SESSION'; end if;
  if v_row.closed_at is not null then return v_row; end if;
  select coalesce(sum(amount_cents), 0) into v_cash from public.kfc_pos_payments where session_id = p_session and method = 'cash';
  update public.kfc_pos_sessions
     set closed_at = now(), closed_by = p_closed_by, counted_cash_cents = p_counted_cents,
         expected_cash_cents = v_row.opening_float_cents + v_cash, note = nullif(trim(coalesce(p_note, '')), '')
   where id = p_session
  returning * into v_row;
  return v_row;
end $$;

-- ---------------------------------------------------------------------------
-- One sale
-- ---------------------------------------------------------------------------
--
-- p_lines:    [{ "article": "AS24-1-...", "quantity": 2, "unit_price_cents": 1995,
--                "discount_cents": 0, "vat_rate": 21 }, ...]   prices incl. VAT
-- p_payments: [{ "method": "cash", "tendered_cents": 5000 }, { "method": "pin", "tendered_cents": 1990 }]
-- p_biller:   { "name": ..., "street": ..., "postcode": ..., "city": ..., "email": ...,
--               "phone": ..., "kvk": ..., "btw": ..., "iban": ... }

create or replace function public.kfc_pos_sale(
  p_session uuid, p_key text, p_lines jsonb, p_payments jsonb,
  p_customer uuid, p_client_name text, p_biller jsonb, p_created_by uuid
) returns uuid language plpgsql as $$
declare
  v_invoice uuid; v_session public.kfc_pos_sessions;
  v_line jsonb; v_pay jsonb; v_i integer := 0;
  v_article public.kfc_articles; v_qty integer; v_price integer; v_disc integer; v_rate numeric;
  v_incl integer; v_total integer := 0; v_vat numeric := 0;
  v_cash integer := 0; v_noncash integer := 0; v_change integer;
  v_method text; v_tendered integer; v_location uuid; v_number text;
begin
  if p_key is null or length(p_key) < 8 or length(p_key) > 80 then raise exception 'KFC_POS_BAD_KEY'; end if;

  -- Retry: the same sale again returns the invoice it already made.
  select id into v_invoice from public.sales_invoices where pos_key = p_key;
  if found then return v_invoice; end if;

  select * into v_session from public.kfc_pos_sessions where id = p_session for update;
  if not found or v_session.closed_at is not null then raise exception 'KFC_POS_CLOSED'; end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 or jsonb_array_length(p_lines) > 200 then
    raise exception 'KFC_POS_BAD_LINES';
  end if;
  if jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) = 0 or jsonb_array_length(p_payments) > 10 then
    raise exception 'KFC_POS_BAD_PAYMENTS';
  end if;

  -- Validate every line and work out the totals before writing anything.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    if not found then raise exception 'KFC_POS_UNKNOWN_ARTICLE'; end if;
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    if v_qty is null or v_qty < 1 or v_qty > 10000 or v_price is null or v_price < 0 or v_price > 10000000
       or v_disc < 0 or v_disc > v_qty * v_price or v_rate not in (0, 9, 21) then
      raise exception 'KFC_POS_BAD_LINES';
    end if;
    v_incl := v_qty * v_price - v_disc;
    v_total := v_total + v_incl;
    v_vat := v_vat + v_incl - v_incl / (1 + v_rate / 100);
  end loop;

  -- Payments: non-cash is taken as entered; cash may exceed what is left (change).
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method not in ('cash', 'pin', 'other') or v_tendered is null or v_tendered <= 0 or v_tendered > 100000000 then
      raise exception 'KFC_POS_BAD_PAYMENTS';
    end if;
    if v_method = 'cash' then v_cash := v_cash + v_tendered; else v_noncash := v_noncash + v_tendered; end if;
  end loop;
  if v_noncash > v_total then raise exception 'KFC_POS_OVERPAID'; end if;
  if v_cash + v_noncash < v_total then raise exception 'KFC_POS_UNDERPAID'; end if;
  v_change := v_cash + v_noncash - v_total;

  insert into public.sales_invoices (
    biller_name, biller_street, biller_postcode, biller_city, biller_email, biller_phone, biller_kvk, biller_btw, biller_iban,
    client_name, notes, subtotal, vat_total, total, status, paid_at, created_by, customer_id, pos_session_id, pos_key
  ) values (
    coalesce(nullif(p_biller->>'name', ''), 'Winkel'), p_biller->>'street', p_biller->>'postcode', p_biller->>'city',
    p_biller->>'email', p_biller->>'phone', p_biller->>'kvk', p_biller->>'btw', p_biller->>'iban',
    coalesce(nullif(trim(coalesce(p_client_name, '')), ''), 'Kassaverkoop'), 'Kassa',
    round((v_total - round(v_vat)) / 100.0, 2), round(round(v_vat) / 100.0, 2), round(v_total / 100.0, 2),
    'betaald', now(), p_created_by, p_customer, p_session, p_key
  ) returning id, invoice_number into v_invoice, v_number;

  -- Lines (excl. VAT per unit) and the stock moves.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_i := v_i + 1;
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    insert into public.sales_invoice_lines (invoice_id, line_no, description, quantity, unit_price, discount, vat_rate)
    values (v_invoice, v_i,
      left(v_article.name || case when v_article.sku <> '' then ' (' || v_article.sku || ')' else '' end, 300),
      v_qty, round(v_price / (1 + v_rate / 100) / 100.0, 2), round(v_disc / (1 + v_rate / 100) / 100.0, 2), v_rate);

    v_location := null;
    select location_id into v_location from public.kfc_stock_levels
     where article_code = v_article.code order by quantity desc, location_id limit 1;
    perform public.kfc_book_move(v_article.code, v_location, -v_qty, 'sale', p_key || ':line:' || v_i,
      null, 'Kassa ' || v_number, null, p_created_by, null, null, null, v_invoice);
  end loop;

  -- Payments: cash keeps tendered minus change.
  v_i := 0;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_i := v_i + 1;
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method = 'cash' then
      if v_change >= v_tendered then v_change := v_change - v_tendered; continue; end if;
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, 'cash', v_tendered - v_change, v_tendered, p_created_by, p_key || ':pay:' || v_i);
      v_change := 0;
    else
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, v_method, v_tendered, v_tendered, p_created_by, p_key || ':pay:' || v_i);
    end if;
  end loop;

  -- A known customer: the trigger posted the invoice to their ledger; settle it now.
  if p_customer is not null and v_total > 0 then
    perform public.kfc_post_entry(p_customer, 'payment', v_total, p_key || ':ledger', null, 'Kassa ' || v_number,
      p_created_by, null, v_invoice);
  end if;

  return v_invoice;
end $$;

-- ---------------------------------------------------------------------------
-- Security: server-only.
-- ---------------------------------------------------------------------------

alter table public.kfc_pos_sessions enable row level security;
alter table public.kfc_pos_payments enable row level security;
revoke all on public.kfc_pos_sessions from anon, authenticated;
revoke all on public.kfc_pos_payments from anon, authenticated;
revoke all on function public.kfc_pos_open(text, integer, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_close(uuid, integer, text, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_sale(uuid, text, jsonb, jsonb, uuid, text, jsonb, uuid) from public, anon, authenticated;

-- ===== 0130_kfc_cariler.sql =====
-- ============================================================================
-- 0130: cariler — customer and supplier accounts, purchasing on supplier
-- accounts (Nebim V3 / ERPNext style: Customer, Supplier, Purchase Order,
-- Purchase Receipt, Purchase Invoice, statement, aging).
--
--   kfc_customers              + kvk, invoice_email, iban, bic, website
--                              (company accounts need KvK and BTW; the app
--                              validates, the database keeps the KvK format).
--   kfc_suppliers              the supplier account (crediteur).
--   kfc_supplier_contacts      people at the supplier.
--   kfc_purchase_orders        + supplier_id, backfilled from the free-text
--                              supplier names (the text column stays as the
--                              name on the order).
--   kfc_supplier_articles      supplier SKU, agreed price, lead time, minimum
--                              quantity, preferred supplier; last price paid
--                              is kept up to date from purchase order lines.
--   kfc_supplier_ledger        append-only, mirrors kfc_customer_ledger (0093):
--                              invoice (+), payment (−), credit_note (−),
--                              refund (+), opening (±), write_off (−),
--                              reversal (opposite). amount_cents > 0 means
--                              we owe the supplier.
--   kfc_supplier_allocations   which payment/credit settles which invoice.
--   kfc_supplier_invoice_open  open remainder per invoice entry.
--   kfc_supplier_balance       open, overdue, aging and open purchase orders.
--   kfc_purchase_line_facts    one row per purchase order line, for reports.
--
--   kfc_post_supplier_entry    books an invoice, payment, credit, refund,
--                              opening or write-off; idempotent on p_key;
--                              credits allocate oldest due first.
--   kfc_reverse_supplier_entry the opposite entry and opposite allocations.
--
-- Server-only like 0090/0093: RLS on, nothing for anon/authenticated.
-- Idempotent: safe to run twice.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Customers: company registration and invoicing fields
-- ---------------------------------------------------------------------------
alter table public.kfc_customers add column if not exists kvk text;
alter table public.kfc_customers add column if not exists invoice_email text;
alter table public.kfc_customers add column if not exists iban text;
alter table public.kfc_customers add column if not exists bic text;
alter table public.kfc_customers add column if not exists website text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'kfc_customers_kvk_format') then
    alter table public.kfc_customers add constraint kfc_customers_kvk_format check (kvk is null or kvk ~ '^[0-9]{8}$');
  end if;
end $$;
create index if not exists kfc_customers_kvk_idx on public.kfc_customers (kvk) where kvk is not null;
create index if not exists kfc_customers_vat_idx on public.kfc_customers (upper(vat_number)) where vat_number is not null;

-- ---------------------------------------------------------------------------
-- Suppliers
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_suppliers (
  id                uuid primary key default gen_random_uuid(),
  name              text not null check (length(btrim(name)) between 1 and 160),
  kvk               text check (kvk is null or kvk ~ '^[0-9]{8}$'),
  vat_number        text,
  iban              text,
  bic               text,
  email             text,
  order_email       text,
  phone             text,
  website           text,
  contact_name      text,
  street            text,
  postcode          text,
  city              text,
  country           text not null default 'NL',
  terms_days        integer not null default 30 check (terms_days between 0 and 180),
  lead_time_days    integer check (lead_time_days is null or lead_time_days between 0 and 365),
  min_order_cents   integer check (min_order_cents is null or min_order_cents >= 0),
  customer_number   text,  -- our account number at this supplier
  note              text,
  active            boolean not null default true,
  created_by        uuid,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create unique index if not exists kfc_suppliers_name_key on public.kfc_suppliers (lower(btrim(name)));
create index if not exists kfc_suppliers_active_idx on public.kfc_suppliers (active, lower(name));

create table if not exists public.kfc_supplier_contacts (
  id           uuid primary key default gen_random_uuid(),
  supplier_id  uuid not null references public.kfc_suppliers (id) on delete cascade,
  name         text not null check (length(btrim(name)) between 1 and 120),
  position     text,
  email        text,
  phone        text,
  created_at   timestamptz not null default now()
);
create index if not exists kfc_supplier_contacts_supplier_idx on public.kfc_supplier_contacts (supplier_id);

-- ---------------------------------------------------------------------------
-- Purchase orders on the supplier account
-- ---------------------------------------------------------------------------
alter table public.kfc_purchase_orders add column if not exists supplier_id uuid references public.kfc_suppliers (id);
create index if not exists kfc_purchase_orders_supplier_idx on public.kfc_purchase_orders (supplier_id, created_at desc);

-- Backfill: one supplier per distinct (case- and space-insensitive) name.
insert into public.kfc_suppliers (name)
select distinct on (lower(btrim(supplier))) btrim(supplier)
  from public.kfc_purchase_orders
 where supplier_id is null and btrim(coalesce(supplier, '')) <> ''
 order by lower(btrim(supplier)), created_at
on conflict (lower(btrim(name))) do nothing;

update public.kfc_purchase_orders po
   set supplier_id = s.id
  from public.kfc_suppliers s
 where po.supplier_id is null
   and lower(btrim(po.supplier)) = lower(btrim(s.name));

-- ---------------------------------------------------------------------------
-- Supplier articles: what this supplier sells us, under which code, at what price
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_supplier_articles (
  supplier_id       uuid not null references public.kfc_suppliers (id) on delete cascade,
  article_code      text not null references public.kfc_articles (code) on delete cascade,
  supplier_sku      text,
  price_cents       integer check (price_cents is null or price_cents >= 0),
  min_qty           integer not null default 1 check (min_qty > 0),
  lead_time_days    integer check (lead_time_days is null or lead_time_days between 0 and 365),
  preferred         boolean not null default false,
  last_price_cents  integer,
  last_ordered_at   timestamptz,
  note              text,
  updated_at        timestamptz not null default now(),
  primary key (supplier_id, article_code)
);
create index if not exists kfc_supplier_articles_article_idx on public.kfc_supplier_articles (article_code);
create index if not exists kfc_supplier_articles_sku_idx on public.kfc_supplier_articles (upper(supplier_sku)) where supplier_sku is not null;
create unique index if not exists kfc_supplier_articles_one_preferred on public.kfc_supplier_articles (article_code) where preferred;

-- A priced purchase order line keeps the supplier-article row current: last
-- price paid, last ordered; the agreed price is only filled when still empty.
create or replace function public.kfc_supplier_article_from_po_line() returns trigger
language plpgsql set search_path = '' as $$
declare v_supplier uuid;
begin
  select supplier_id into v_supplier from public.kfc_purchase_orders where id = new.po_id;
  if v_supplier is null then return new; end if;
  insert into public.kfc_supplier_articles as sa (supplier_id, article_code, price_cents, last_price_cents, last_ordered_at)
  values (v_supplier, new.article_code, new.unit_cost_cents, new.unit_cost_cents, now())
  on conflict (supplier_id, article_code) do update
    set last_price_cents = coalesce(excluded.last_price_cents, sa.last_price_cents),
        price_cents      = coalesce(sa.price_cents, excluded.price_cents),
        last_ordered_at  = now(),
        updated_at       = now();
  return new;
end $$;
drop trigger if exists kfc_supplier_article_from_po_line on public.kfc_purchase_order_lines;
create trigger kfc_supplier_article_from_po_line after insert or update of unit_cost_cents on public.kfc_purchase_order_lines
  for each row execute function public.kfc_supplier_article_from_po_line();

-- Existing priced lines seed the table once (latest price per supplier and article).
insert into public.kfc_supplier_articles (supplier_id, article_code, price_cents, last_price_cents, last_ordered_at)
select distinct on (po.supplier_id, l.article_code) po.supplier_id, l.article_code, l.unit_cost_cents, l.unit_cost_cents, coalesce(po.ordered_at, po.created_at)
  from public.kfc_purchase_order_lines l
  join public.kfc_purchase_orders po on po.id = l.po_id
 where po.supplier_id is not null
 order by po.supplier_id, l.article_code, (l.unit_cost_cents is null), coalesce(po.ordered_at, po.created_at) desc
on conflict (supplier_id, article_code) do nothing;

-- ---------------------------------------------------------------------------
-- Supplier ledger (crediteuren), mirroring the customer ledger of 0093/0094
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_supplier_ledger (
  id                 bigserial primary key,
  supplier_id        uuid not null references public.kfc_suppliers (id),
  entry_type         text not null check (entry_type in ('invoice', 'payment', 'credit_note', 'refund', 'opening', 'write_off', 'reversal')),
  amount_cents       integer not null,
  vat_cents          integer not null default 0,
  entry_date         date not null default (now() at time zone 'Europe/Amsterdam')::date,
  due_date           date,
  booked_at          timestamptz not null default now(),
  invoice_ref        text,
  purchase_order_id  uuid references public.kfc_purchase_orders (id) on delete set null,
  reverses_entry_id  bigint references public.kfc_supplier_ledger (id),
  note               text,
  created_by         uuid,
  idempotency_key    text not null unique
);
create index if not exists kfc_supplier_ledger_supplier_idx on public.kfc_supplier_ledger (supplier_id, entry_date desc, booked_at desc, id desc);
create index if not exists kfc_supplier_ledger_po_idx on public.kfc_supplier_ledger (purchase_order_id) where purchase_order_id is not null;
create index if not exists kfc_supplier_ledger_reverses_idx on public.kfc_supplier_ledger (reverses_entry_id) where reverses_entry_id is not null;

create table if not exists public.kfc_supplier_allocations (
  id                bigserial primary key,
  credit_entry_id   bigint not null references public.kfc_supplier_ledger (id),
  invoice_entry_id  bigint not null references public.kfc_supplier_ledger (id),
  amount_cents      integer not null,
  created_at        timestamptz not null default now()
);
create index if not exists kfc_supplier_alloc_invoice_idx on public.kfc_supplier_allocations (invoice_entry_id);
create index if not exists kfc_supplier_alloc_credit_idx on public.kfc_supplier_allocations (credit_entry_id);

-- Open remainder of every debit entry we still owe (invoice, opening, refund).
-- Reversals and reversed entries are never open themselves (as 0094).
create or replace view public.kfc_supplier_invoice_open as
select e.id as entry_id, e.supplier_id, e.entry_type, e.entry_date, e.due_date, e.invoice_ref, e.purchase_order_id, e.amount_cents,
       e.amount_cents - coalesce((select sum(a.amount_cents) from public.kfc_supplier_allocations a where a.invoice_entry_id = e.id), 0) as open_cents
  from public.kfc_supplier_ledger e
 where e.amount_cents > 0
   and e.entry_type <> 'reversal'
   and not exists (select 1 from public.kfc_supplier_ledger r where r.reverses_entry_id = e.id);

-- Balance, aging by due date and open purchase orders, per supplier.
create or replace view public.kfc_supplier_balance as
with open as (
  select supplier_id,
         sum(open_cents) filter (where open_cents > 0 and (due_date is null or due_date >= current_date)) as not_due,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 1 and 30)  as d1_30,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 31 and 60) as d31_60,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 61 and 90) as d61_90,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date > 90)              as d90p,
         min(due_date) filter (where open_cents > 0 and due_date < current_date) as oldest_overdue
    from public.kfc_supplier_invoice_open group by supplier_id
), bal as (
  select supplier_id, sum(amount_cents) as open_cents, max(entry_date) as last_entry from public.kfc_supplier_ledger group by supplier_id
), lines as (
  select po_id, sum(greatest(quantity - received, 0)::bigint * coalesce(unit_cost_cents, 0)) as open_value
    from public.kfc_purchase_order_lines group by po_id
), po as (
  select o.supplier_id,
         count(*) filter (where o.status in ('draft', 'ordered')) as open_pos,
         count(*) filter (where o.status = 'ordered' and o.expected_on < current_date) as late_pos,
         coalesce(sum(l.open_value) filter (where o.status = 'ordered'), 0) as on_order_cents,
         max(coalesce(o.ordered_at, o.created_at)) as last_order_at
    from public.kfc_purchase_orders o
    left join lines l on l.po_id = o.id
   where o.supplier_id is not null
   group by o.supplier_id
)
select s.id as supplier_id,
       coalesce(b.open_cents, 0) as open_cents,
       coalesce(o.d1_30, 0) + coalesce(o.d31_60, 0) + coalesce(o.d61_90, 0) + coalesce(o.d90p, 0) as overdue_cents,
       coalesce(o.not_due, 0) as not_due, coalesce(o.d1_30, 0) as d1_30, coalesce(o.d31_60, 0) as d31_60,
       coalesce(o.d61_90, 0) as d61_90, coalesce(o.d90p, 0) as d90p, o.oldest_overdue, b.last_entry,
       coalesce(p.open_pos, 0) as open_pos, coalesce(p.late_pos, 0) as late_pos,
       coalesce(p.on_order_cents, 0) as on_order_cents, p.last_order_at
  from public.kfc_suppliers s
  left join open o on o.supplier_id = s.id
  left join bal  b on b.supplier_id = s.id
  left join po   p on p.supplier_id = s.id;

-- One row per purchase order line: purchases per supplier / period / article,
-- open orders, late deliveries and purchase price history all read this.
create or replace view public.kfc_purchase_line_facts as
select l.id as line_id, o.id as po_id, o.status, o.supplier_id, coalesce(s.name, o.supplier) as supplier_name,
       o.created_at, o.ordered_at, o.expected_on, o.received_at, o.invoice_ref,
       (coalesce(o.ordered_at, o.created_at) at time zone 'Europe/Amsterdam')::date as order_date,
       l.article_code, a.name as article_name, a.sku, a.category,
       l.quantity, l.received, greatest(l.quantity - l.received, 0) as open_quantity, l.unit_cost_cents,
       l.quantity::bigint * l.unit_cost_cents as ordered_cents,
       l.received::bigint * l.unit_cost_cents as received_cents,
       (select max(m.created_at) from public.kfc_stock_moves m where m.purchase_order_line_id = l.id and m.reason = 'received') as last_receipt_at
  from public.kfc_purchase_order_lines l
  join public.kfc_purchase_orders o on o.id = l.po_id
  left join public.kfc_articles a on a.code = l.article_code
  left join public.kfc_suppliers s on s.id = o.supplier_id;

-- ---------------------------------------------------------------------------
-- Booking
-- ---------------------------------------------------------------------------
-- p_allocations: [{"invoice_entry_id": 12, "amount_cents": 5000}] or null for oldest-due-first.
create or replace function public.kfc_post_supplier_entry(
  p_supplier uuid, p_type text, p_amount_cents integer, p_key text,
  p_entry_date date default null, p_due_date date default null, p_invoice_ref text default null,
  p_purchase_order uuid default null, p_vat_cents integer default 0, p_note text default null,
  p_created_by uuid default null, p_allocations jsonb default null
) returns bigint language plpgsql set search_path = '' as $$
declare
  v_id bigint; v_signed integer; v_left integer; v_inv record; v_take integer; v_alloc jsonb;
  v_terms integer; v_date date; v_ref text; v_po_supplier uuid;
begin
  if p_type not in ('invoice', 'payment', 'credit_note', 'refund', 'opening', 'write_off') then raise exception 'KFC_BAD_TYPE'; end if;
  if p_type <> 'opening' and (p_amount_cents is null or p_amount_cents <= 0) then raise exception 'KFC_BAD_AMOUNT'; end if;
  if p_type = 'opening' and coalesce(p_amount_cents, 0) = 0 then raise exception 'KFC_BAD_AMOUNT'; end if;
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;

  perform pg_advisory_xact_lock(hashtext('kfc_supplier_ledger:' || p_supplier::text));
  -- A retry that raced the first attempt finds its entry after the lock.
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  select terms_days into v_terms from public.kfc_suppliers where id = p_supplier;
  if not found then raise exception 'KFC_NO_SUPPLIER'; end if;

  v_date := coalesce(p_entry_date, (now() at time zone 'Europe/Amsterdam')::date);
  v_ref := nullif(btrim(coalesce(p_invoice_ref, '')), '');

  if p_purchase_order is not null then
    select supplier_id into v_po_supplier from public.kfc_purchase_orders where id = p_purchase_order;
    if not found then raise exception 'KFC_NO_PO'; end if;
    if v_po_supplier is distinct from p_supplier then raise exception 'KFC_PO_SUPPLIER'; end if;
  end if;

  if p_type = 'invoice' then
    if v_ref is null then raise exception 'KFC_INVOICE_REF'; end if;
    if exists (select 1 from public.kfc_supplier_ledger e
                where e.supplier_id = p_supplier and e.entry_type = 'invoice' and lower(e.invoice_ref) = lower(v_ref)
                  and not exists (select 1 from public.kfc_supplier_ledger r where r.reverses_entry_id = e.id)) then
      raise exception 'KFC_DUPLICATE_INVOICE';
    end if;
  end if;

  v_signed := case when p_type in ('payment', 'credit_note', 'write_off') then -p_amount_cents else p_amount_cents end;
  insert into public.kfc_supplier_ledger (supplier_id, entry_type, amount_cents, vat_cents, entry_date, due_date, invoice_ref, purchase_order_id, note, created_by, idempotency_key)
  values (p_supplier, p_type, v_signed, case when p_type = 'invoice' then coalesce(p_vat_cents, 0) else 0 end, v_date,
          case when p_type in ('invoice', 'opening', 'refund') then coalesce(p_due_date, v_date + coalesce(v_terms, 30)) end,
          v_ref, p_purchase_order, nullif(btrim(coalesce(p_note, '')), ''), p_created_by, p_key)
  returning id into v_id;

  -- The supplier's invoice number lands on the order when the order has none yet.
  if p_type = 'invoice' and p_purchase_order is not null then
    update public.kfc_purchase_orders set invoice_ref = v_ref where id = p_purchase_order and invoice_ref is null;
  end if;

  if v_signed >= 0 then return v_id; end if;

  v_left := -v_signed;
  if p_allocations is not null then
    for v_alloc in select * from jsonb_array_elements(p_allocations) loop
      v_take := least((v_alloc->>'amount_cents')::integer, v_left);
      exit when v_take is null or v_take <= 0;
      select o.entry_id, o.open_cents into v_inv from public.kfc_supplier_invoice_open o
       where o.entry_id = (v_alloc->>'invoice_entry_id')::bigint and o.supplier_id = p_supplier;
      if not found then raise exception 'KFC_BAD_ALLOCATION'; end if;
      v_take := least(v_take, greatest(v_inv.open_cents, 0));
      continue when v_take <= 0;
      insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_id, v_inv.entry_id, v_take);
      v_left := v_left - v_take;
    end loop;
  end if;
  -- Whatever the explicit allocations did not use goes oldest due first.
  for v_inv in select entry_id, open_cents from public.kfc_supplier_invoice_open
                where supplier_id = p_supplier and open_cents > 0
                order by due_date nulls last, entry_date, entry_id loop
    exit when v_left <= 0;
    v_take := least(v_inv.open_cents, v_left);
    insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_id, v_inv.entry_id, v_take);
    v_left := v_left - v_take;
  end loop;
  return v_id;
end $$;

create or replace function public.kfc_reverse_supplier_entry(p_entry bigint, p_key text, p_created_by uuid default null, p_note text default null)
returns bigint language plpgsql set search_path = '' as $$
declare v_orig public.kfc_supplier_ledger; v_id bigint; v_a record;
begin
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  select * into v_orig from public.kfc_supplier_ledger where id = p_entry;
  if not found then raise exception 'KFC_NO_ENTRY'; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_supplier_ledger:' || v_orig.supplier_id::text));
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  if v_orig.entry_type = 'reversal' then raise exception 'KFC_ALREADY_REVERSED'; end if;
  if exists (select 1 from public.kfc_supplier_ledger where reverses_entry_id = p_entry) then raise exception 'KFC_ALREADY_REVERSED'; end if;
  insert into public.kfc_supplier_ledger (supplier_id, entry_type, amount_cents, vat_cents, entry_date, invoice_ref, purchase_order_id, reverses_entry_id, note, created_by, idempotency_key)
  values (v_orig.supplier_id, 'reversal', -v_orig.amount_cents, -v_orig.vat_cents, (now() at time zone 'Europe/Amsterdam')::date,
          v_orig.invoice_ref, v_orig.purchase_order_id, p_entry, coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Tegenboeking van #' || p_entry::text), p_created_by, p_key)
  returning id into v_id;
  for v_a in select * from public.kfc_supplier_allocations where credit_entry_id = p_entry or invoice_entry_id = p_entry loop
    insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_a.credit_entry_id, v_a.invoice_entry_id, -v_a.amount_cents);
  end loop;
  return v_id;
end $$;

-- ---------------------------------------------------------------------------
-- Server only
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['kfc_suppliers', 'kfc_supplier_contacts', 'kfc_supplier_articles', 'kfc_supplier_ledger', 'kfc_supplier_allocations'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;
revoke all on public.kfc_supplier_invoice_open from public, anon, authenticated;
revoke all on public.kfc_supplier_balance from public, anon, authenticated;
revoke all on public.kfc_purchase_line_facts from public, anon, authenticated;
grant select on public.kfc_supplier_invoice_open, public.kfc_supplier_balance, public.kfc_purchase_line_facts to service_role;
grant usage, select on sequence public.kfc_supplier_ledger_id_seq, public.kfc_supplier_allocations_id_seq to service_role;
revoke all on function public.kfc_post_supplier_entry(uuid, text, integer, text, date, date, text, uuid, integer, text, uuid, jsonb) from public, anon, authenticated;
revoke all on function public.kfc_reverse_supplier_entry(bigint, text, uuid, text) from public, anon, authenticated;
revoke all on function public.kfc_supplier_article_from_po_line() from public, anon, authenticated;
grant execute on function public.kfc_post_supplier_entry(uuid, text, integer, text, date, date, text, uuid, integer, text, uuid, jsonb) to service_role;
grant execute on function public.kfc_reverse_supplier_entry(bigint, text, uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ===== 0131_kfc_inventory_reports.sql =====
-- ============================================================================
-- 0131: KeyForCars inventory lists and owner reports (Nebim / ERPNext level).
--
-- Read-only views and report functions over the ledger of 0090 and later. Nothing
-- here writes stock; every number is derived from kfc_stock_moves,
-- kfc_stock_levels, kfc_purchase_order_lines and the documents a move links to.
--
--   kfc_article_overview     one row per article: master data, the five stock
--                            numbers, minimum, value at purchase price, last
--                            supplier, last receipt / sale, sales 30 / 90 / 365
--                            days and a stock state (negatief · nul · laag ·
--                            op_voorraad). The article master list pages,
--                            filters and sorts on this view through PostgREST.
--   kfc_sales_lines          every 'sale' and 'return' move as a sales line with
--                            channel (webshop · kassa · factuur · overig), revenue
--                            excl. VAT and cost. Returns are negative lines.
--   kfc_sales_report()       sales per article / category / day / month / channel
--   kfc_article_movement()   per article: stock, sold, revenue, profit, cover days
--                            (slow / fast movers and ABC)
--   kfc_stock_valuation()    quantity and value per article and location on a date
--   kfc_stock_ledger()       every move with a running balance per article
--   kfc_stock_ageing()       FIFO ageing of the current stock in day buckets
--   kfc_article_totals()     counts and stock value for the article list header
--
-- Revenue rules (also in docs/voorraad-rapporten.md):
--   webshop  the order line's total excl. VAT, pro rata the moved quantity;
--   invoice  (kassa and other invoices) the invoice line whose description is the
--            article name (+ " (SKU)"), as kfc_pos_sale writes it; when no line
--            matches, the article's shelf price / 1.21 and the row is flagged
--            revenue_estimated;
--   cost     the move's unit_cost_cents, else the article's current purchase
--            price (flagged cost_estimated).
--
-- Install isolation: these objects only read tables of the database they are
-- created in; KeyForCars and Autosleutel24 each run their own Supabase project.
--
-- Server-only like 0090: nothing for anon or authenticated, select / execute for
-- service_role only. Idempotent: create or replace / if not exists throughout.
-- ============================================================================

-- Indexes the reports filter on -----------------------------------------------
create index if not exists kfc_stock_moves_reason_time_idx on public.kfc_stock_moves (reason, created_at);
create index if not exists kfc_stock_moves_invoice_idx on public.kfc_stock_moves (sales_invoice_id) where sales_invoice_id is not null;
create index if not exists kfc_stock_moves_order_line_idx on public.kfc_stock_moves (order_line_id) where order_line_id is not null;
create index if not exists kfc_stock_moves_location_time_idx on public.kfc_stock_moves (location_id, created_at);
create index if not exists kfc_stock_moves_batch_idx on public.kfc_stock_moves (count_batch_id) where count_batch_id is not null;
create index if not exists kfc_articles_category_idx on public.kfc_articles (category);
create index if not exists kfc_articles_status_idx on public.kfc_articles (status);

-- ---------------------------------------------------------------------------
-- Sales lines
-- ---------------------------------------------------------------------------
create or replace view public.kfc_sales_lines as
select
  m.id                                                   as move_id,
  m.created_at,
  (m.created_at at time zone 'Europe/Amsterdam')::date   as day,
  m.article_code,
  a.name,
  a.sku,
  a.category,
  m.reason,
  -m.delta                                               as quantity,  -- sale +, return −
  case
    when m.order_line_id is not null then 'webshop'
    when m.sales_invoice_id is not null and coalesce(m.note, '') like 'Kassa %' then 'kassa'
    when m.sales_invoice_id is not null then 'factuur'
    else 'overig'
  end                                                    as channel,
  so.shop,
  coalesce(so.number, si.invoice_number)                 as document,
  m.order_line_id,
  m.sales_invoice_id,
  case
    when sl.id is not null and sl.quantity > 0
      then round(coalesce(sl.total_excl_cents, 0)::numeric * (-m.delta) / sl.quantity)::bigint
    when il.unit_price is not null
      then round((il.unit_price * il.quantity - il.discount) / il.quantity * 100 * (-m.delta))::bigint
    else round(coalesce(a.sale_price_cents, 0)::numeric / 1.21 * (-m.delta))::bigint
  end                                                    as revenue_cents,
  (sl.id is null and il.unit_price is null)              as revenue_estimated,
  (coalesce(m.unit_cost_cents, a.purchase_price_cents, 0)::bigint * (-m.delta)) as cost_cents,
  (m.unit_cost_cents is null)                            as cost_estimated
from public.kfc_stock_moves m
join public.kfc_articles a on a.code = m.article_code
left join public.kfc_shop_order_lines sl on sl.id = m.order_line_id
left join public.kfc_shop_orders so on so.id = sl.order_id
left join public.sales_invoices si on si.id = m.sales_invoice_id
left join lateral (
  select l.unit_price, l.quantity, l.discount
  from public.sales_invoice_lines l
  where m.sales_invoice_id is not null and l.invoice_id = m.sales_invoice_id
    and l.description in (a.name, left(a.name || case when a.sku <> '' then ' (' || a.sku || ')' else '' end, 300))
  order by l.line_no
  limit 1
) il on true
where m.reason in ('sale', 'return');

-- ---------------------------------------------------------------------------
-- Article overview (master list)
-- ---------------------------------------------------------------------------
create or replace view public.kfc_article_overview as
with levels as (
  select l.article_code,
         sum(l.minimum) filter (where loc.kind = 'shelf')                                   as minimum,
         array_agg(distinct loc.warehouse) filter (where l.quantity <> 0)                   as warehouses,
         array_agg(distinct loc.warehouse || '/' || loc.shelf || '/' || loc.box)
           filter (where l.quantity <> 0)                                                    as locations,
         max(l.last_counted_at)                                                              as last_counted_at
  from public.kfc_stock_levels l
  join public.kfc_locations loc on loc.id = l.location_id
  group by l.article_code
), moves as (
  select article_code,
         max(created_at) filter (where reason in ('received', 'assembly') and delta > 0) as last_received_at,
         max(created_at) filter (where reason = 'sale')                                  as last_sold_at,
         max(created_at)                                                                  as last_move_at,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '30 days'), 0)  as sold_30d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '90 days'), 0)  as sold_90d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '365 days'), 0) as sold_365d
  from public.kfc_stock_moves
  group by article_code
), suppliers as (
  select pl.article_code,
         array_agg(distinct po.supplier)                                                   as suppliers,
         (array_agg(po.supplier order by coalesce(po.ordered_at, po.created_at) desc))[1]  as last_supplier,
         (array_agg(pl.unit_cost_cents order by coalesce(po.ordered_at, po.created_at) desc)
            filter (where pl.unit_cost_cents is not null))[1]                              as last_po_cost_cents
  from public.kfc_purchase_order_lines pl
  join public.kfc_purchase_orders po on po.id = pl.po_id
  where po.status <> 'cancelled'
  group by pl.article_code
)
select
  a.code, a.name, a.sku, a.ean, a.category, a.status, a.condition, a.tracking, a.supplier_ref,
  a.sale_price_cents, a.purchase_price_cents, a.photo_version, a.created_at, a.updated_at,
  p.physical, p.unusable, p.reserved, p.available, p.incoming,
  coalesce(lv.minimum, 0)::integer                                                   as minimum,
  (greatest(p.physical - p.unusable, 0)::bigint * coalesce(a.purchase_price_cents, 0)) as stock_value_cents,
  (a.purchase_price_cents is null)                                                   as unpriced,
  coalesce(lv.warehouses, '{}')                                                      as warehouses,
  coalesce(lv.locations, '{}')                                                       as locations,
  lv.last_counted_at,
  coalesce(s.suppliers, '{}')                                                        as suppliers,
  s.last_supplier,
  s.last_po_cost_cents,
  mv.last_received_at, mv.last_sold_at, mv.last_move_at,
  coalesce(mv.sold_30d, 0)::integer  as sold_30d,
  coalesce(mv.sold_90d, 0)::integer  as sold_90d,
  coalesce(mv.sold_365d, 0)::integer as sold_365d,
  case
    when p.physical < 0 then 'negatief'
    when p.physical = 0 then 'nul'
    when coalesce(lv.minimum, 0) > 0 and p.available <= lv.minimum then 'laag'
    else 'op_voorraad'
  end as stock_state,
  case when a.sale_price_cents is null or a.purchase_price_cents is null or a.sale_price_cents = 0 then null
       else round((a.sale_price_cents / 1.21 - a.purchase_price_cents) / (a.sale_price_cents / 1.21) * 100, 1)
  end as margin_pct
from public.kfc_articles a
join public.kfc_stock_position p on p.article_code = a.code
left join levels lv on lv.article_code = a.code
left join moves mv on mv.article_code = a.code
left join suppliers s on s.article_code = a.code;

-- ---------------------------------------------------------------------------
-- Sales report: grouped sales lines for a period.
-- p_group: article · category · day · month · channel · shop
-- ---------------------------------------------------------------------------
create or replace function public.kfc_sales_report(
  p_from date, p_to date, p_group text default 'article',
  p_category text default '', p_channel text default '', p_query text default ''
) returns table (
  key text, label text, category text, quantity bigint, lines bigint,
  revenue_cents bigint, cost_cents bigint, profit_cents bigint, margin_pct numeric,
  estimated bigint, first_at timestamptz, last_at timestamptz
) language sql stable set search_path = '' as $$
  with scoped as (
    select s.*,
      case p_group
        when 'category' then coalesce(nullif(s.category, ''), '(geen categorie)')
        when 'day'      then to_char(s.day, 'YYYY-MM-DD')
        when 'month'    then to_char(s.day, 'YYYY-MM')
        when 'channel'  then s.channel
        when 'shop'     then coalesce(s.shop, s.channel)
        else s.article_code
      end as k
    from public.kfc_sales_lines s
    where s.day between p_from and p_to
      and (p_category = '' or s.category = p_category)
      and (p_channel = '' or s.channel = p_channel)
      and (p_query = '' or strpos(lower(s.article_code), lower(p_query)) > 0
           or strpos(lower(s.name), lower(p_query)) > 0 or strpos(lower(s.sku), lower(p_query)) > 0)
  )
  select k,
    case when p_group = 'article' then max(name) else k end,
    case when p_group = 'article' then max(category) else null end,
    sum(quantity)::bigint, count(*)::bigint,
    sum(revenue_cents)::bigint, sum(cost_cents)::bigint, (sum(revenue_cents) - sum(cost_cents))::bigint,
    case when sum(revenue_cents) = 0 then null
         else round((sum(revenue_cents) - sum(cost_cents))::numeric / sum(revenue_cents) * 100, 1) end,
    count(*) filter (where revenue_estimated or cost_estimated)::bigint,
    min(created_at), max(created_at)
  from scoped
  group by k
  order by case when p_group in ('day', 'month') then k end, sum(revenue_cents) desc;
$$;

-- ---------------------------------------------------------------------------
-- Article movement: slow / fast movers and ABC (classification done in the app).
-- ---------------------------------------------------------------------------
create or replace function public.kfc_article_movement(p_from date, p_to date, p_category text default '')
returns table (
  code text, name text, sku text, category text, status text,
  physical integer, available integer, stock_value_cents bigint,
  sold bigint, revenue_cents bigint, profit_cents bigint,
  last_sold_at timestamptz, last_received_at timestamptz, days_cover numeric
) language sql stable set search_path = '' as $$
  with sales as (
    select article_code, sum(quantity)::bigint as sold, sum(revenue_cents)::bigint as revenue,
           (sum(revenue_cents) - sum(cost_cents))::bigint as profit
    from public.kfc_sales_lines
    where day between p_from and p_to
    group by article_code
  )
  select o.code, o.name, o.sku, o.category, o.status,
    o.physical::integer, o.available::integer, o.stock_value_cents,
    coalesce(s.sold, 0), coalesce(s.revenue, 0), coalesce(s.profit, 0),
    o.last_sold_at, o.last_received_at,
    case when coalesce(s.sold, 0) <= 0 then null
         else round(o.physical::numeric / (s.sold::numeric / greatest(p_to - p_from + 1, 1)), 0) end
  from public.kfc_article_overview o
  left join sales s on s.article_code = o.code
  where (p_category = '' or o.category = p_category)
    and (o.physical <> 0 or s.article_code is not null);
$$;

-- ---------------------------------------------------------------------------
-- Stock valuation on a date (end of that day, Amsterdam), per article and
-- location, from the ledger. Value at the last known unit cost on that date
-- (receipts / assemblies), else the current purchase price. Quarantine stock
-- is listed with value 0.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_valuation(p_date date, p_warehouse text default '', p_category text default '')
returns table (
  article_code text, name text, sku text, category text,
  location_id uuid, warehouse text, shelf text, box text, kind text, technician_id uuid,
  quantity bigint, unit_cost_cents integer, value_cents bigint, cost_estimated boolean
) language sql stable set search_path = '' as $$
  with bound as (select (p_date + 1)::timestamp at time zone 'Europe/Amsterdam' as ends),
  qty as (
    select m.article_code, m.location_id, sum(m.delta)::bigint as quantity
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends
    group by m.article_code, m.location_id
    having sum(m.delta) <> 0
  ), cost as (
    select distinct on (m.article_code) m.article_code, m.unit_cost_cents
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends and m.delta > 0 and m.reason in ('received', 'assembly')
      and m.unit_cost_cents is not null
    order by m.article_code, m.created_at desc, m.id desc
  )
  select q.article_code, a.name, a.sku, a.category,
    q.location_id, coalesce(loc.warehouse, '(geen locatie)'), loc.shelf, loc.box, coalesce(loc.kind, 'shelf'), loc.technician_id,
    q.quantity,
    coalesce(c.unit_cost_cents, a.purchase_price_cents),
    case when coalesce(loc.kind, 'shelf') = 'quarantine' then 0::bigint
         else greatest(q.quantity, 0) * coalesce(c.unit_cost_cents, a.purchase_price_cents, 0) end,
    c.unit_cost_cents is null
  from qty q
  join public.kfc_articles a on a.code = q.article_code
  left join public.kfc_locations loc on loc.id = q.location_id
  left join cost c on c.article_code = q.article_code
  where (p_warehouse = '' or coalesce(loc.warehouse, '(geen locatie)') = p_warehouse)
    and (p_category = '' or a.category = p_category);
$$;

-- ---------------------------------------------------------------------------
-- Stock ledger: every move in the period with the article's running balance
-- (all locations) after the move, plus the opening balance before the period.
-- One page at a time; p_page_size 0 = everything (for export, capped at 50 000).
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_ledger(
  p_from date, p_to date, p_article text default '', p_reason text default '', p_warehouse text default '',
  p_query text default '', p_page integer default 1, p_page_size integer default 100
) returns jsonb language sql stable set search_path = '' as $$
  with bounds as (
    select p_from::timestamp at time zone 'Europe/Amsterdam' as starts,
           (p_to + 1)::timestamp at time zone 'Europe/Amsterdam' as ends
  ), arts as (
    select a.code, a.name, a.sku, a.category, a.purchase_price_cents from public.kfc_articles a
    where (p_article = '' or a.code = p_article)
      and (p_query = '' or strpos(lower(a.code), lower(p_query)) > 0 or strpos(lower(a.name), lower(p_query)) > 0
           or strpos(lower(a.sku), lower(p_query)) > 0)
  ), running as (
    select m.id, m.created_at, m.article_code, m.location_id, m.delta, m.quantity_after, m.reason,
      m.unit_cost_cents, m.note, m.order_line_id, m.sales_invoice_id, m.purchase_order_line_id, m.count_batch_id, m.created_by,
      sum(m.delta) over (partition by m.article_code order by m.created_at, m.id) as balance
    from public.kfc_stock_moves m
    join arts on arts.code = m.article_code
    cross join bounds
    where m.created_at < bounds.ends
  ), period as (
    select r.*, arts.name, arts.sku, arts.category,
      loc.warehouse, loc.shelf, loc.box,
      coalesce(r.unit_cost_cents, arts.purchase_price_cents) * r.delta as value_cents,
      po.supplier, so.number as order_number, si.invoice_number
    from running r
    join arts on arts.code = r.article_code
    cross join bounds
    left join public.kfc_locations loc on loc.id = r.location_id
    left join public.kfc_purchase_order_lines pl on pl.id = r.purchase_order_line_id
    left join public.kfc_purchase_orders po on po.id = pl.po_id
    left join public.kfc_shop_order_lines sl on sl.id = r.order_line_id
    left join public.kfc_shop_orders so on so.id = sl.order_id
    left join public.sales_invoices si on si.id = r.sales_invoice_id
    where r.created_at >= bounds.starts
      and (p_reason = '' or r.reason = p_reason)
      and (p_warehouse = '' or loc.warehouse = p_warehouse)
  ), opening as (
    select coalesce(sum(m.delta), 0) as qty
    from public.kfc_stock_moves m join arts on arts.code = m.article_code cross join bounds
    where m.created_at < bounds.starts
  ), totals as (
    select count(*) as n,
      coalesce(sum(delta) filter (where delta > 0), 0) as incoming,
      coalesce(-sum(delta) filter (where delta < 0), 0) as outgoing
    from period
  )
  select jsonb_build_object(
    'opening', (select qty from opening),
    'count', totals.n, 'incoming', totals.incoming, 'outgoing', totals.outgoing,
    'rows', coalesce((
      select jsonb_agg(to_jsonb(v) order by v.created_at desc, v.id desc) from (
        select * from period order by created_at desc, id desc
        limit case when p_page_size <= 0 then 50000 else p_page_size end
        offset case when p_page_size <= 0 then 0 else (greatest(p_page, 1)::bigint - 1) * p_page_size end
      ) v), '[]'::jsonb)
  ) from totals;
$$;

-- ---------------------------------------------------------------------------
-- Stock ageing (FIFO): the current physical stock is taken to be the most
-- recent inbound moves (receipt, assembly, return, positive count/correction;
-- transfers are internal and skipped). Stock older than every recorded inbound
-- has an unknown age and is counted in the oldest bucket.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_ageing(p_category text default '')
returns table (
  code text, name text, sku text, category text, physical integer, unit_cost_cents integer, value_cents bigint,
  q_0_30 bigint, q_31_60 bigint, q_61_90 bigint, q_91_180 bigint, q_181_365 bigint, q_365p bigint,
  oldest_days integer, avg_days numeric, last_received_at timestamptz, last_sold_at timestamptz
) language sql stable set search_path = '' as $$
  with stock as (
    select o.code, o.name, o.sku, o.category, o.physical, o.purchase_price_cents, o.last_received_at, o.last_sold_at
    from public.kfc_article_overview o
    where o.physical > 0 and (p_category = '' or o.category = p_category)
  ), inbound as (
    select m.article_code, m.created_at, m.delta,
      sum(m.delta) over (partition by m.article_code order by m.created_at desc, m.id desc) as cum
    from public.kfc_stock_moves m
    join stock s on s.code = m.article_code
    where m.delta > 0 and m.reason <> 'transfer'
  ), alloc as (
    select i.article_code,
      greatest(0, least(i.delta, s.physical - (i.cum - i.delta)))::bigint as qty,
      (now() at time zone 'Europe/Amsterdam')::date - (i.created_at at time zone 'Europe/Amsterdam')::date as age
    from inbound i join stock s on s.code = i.article_code
  ), known as (
    select article_code,
      sum(qty) as qty,
      sum(qty) filter (where age <= 30) as a30, sum(qty) filter (where age between 31 and 60) as a60,
      sum(qty) filter (where age between 61 and 90) as a90, sum(qty) filter (where age between 91 and 180) as a180,
      sum(qty) filter (where age between 181 and 365) as a365, sum(qty) filter (where age > 365) as a365p,
      max(age) filter (where qty > 0) as oldest,
      sum(qty * age) as weighted
    from alloc group by article_code
  )
  select s.code, s.name, s.sku, s.category, s.physical::integer, s.purchase_price_cents,
    s.physical::bigint * coalesce(s.purchase_price_cents, 0),
    coalesce(k.a30, 0)::bigint, coalesce(k.a60, 0)::bigint, coalesce(k.a90, 0)::bigint,
    coalesce(k.a180, 0)::bigint, coalesce(k.a365, 0)::bigint,
    (coalesce(k.a365p, 0) + greatest(s.physical - coalesce(k.qty, 0), 0))::bigint,
    case when s.physical > coalesce(k.qty, 0) then null else k.oldest end::integer,
    case when coalesce(k.qty, 0) = 0 then null else round(k.weighted::numeric / k.qty, 0) end,
    s.last_received_at, s.last_sold_at
  from stock s left join known k on k.article_code = s.code;
$$;

-- ---------------------------------------------------------------------------
-- Header totals of the article list in one pass over the overview.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_article_totals()
returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'articles', count(*),
    'in_stock', count(*) filter (where physical > 0),
    'low',      count(*) filter (where stock_state = 'laag'),
    'zero',     count(*) filter (where stock_state = 'nul'),
    'negative', count(*) filter (where stock_state = 'negatief'),
    'incoming', count(*) filter (where incoming > 0),
    'value',    coalesce(sum(stock_value_cents), 0),
    'unpriced', count(*) filter (where unpriced and physical > 0)
  ) from public.kfc_article_overview;
$$;

-- Security ---------------------------------------------------------------------
revoke all on public.kfc_sales_lines from public, anon, authenticated;
revoke all on public.kfc_article_overview from public, anon, authenticated;
grant select on public.kfc_sales_lines to service_role;
grant select on public.kfc_article_overview to service_role;

revoke all on function public.kfc_sales_report(date, date, text, text, text, text) from public, anon, authenticated;
revoke all on function public.kfc_article_movement(date, date, text) from public, anon, authenticated;
revoke all on function public.kfc_stock_valuation(date, text, text) from public, anon, authenticated;
revoke all on function public.kfc_stock_ledger(date, date, text, text, text, text, integer, integer) from public, anon, authenticated;
revoke all on function public.kfc_stock_ageing(text) from public, anon, authenticated;
revoke all on function public.kfc_article_totals() from public, anon, authenticated;
grant execute on function public.kfc_sales_report(date, date, text, text, text, text) to service_role;
grant execute on function public.kfc_article_movement(date, date, text) to service_role;
grant execute on function public.kfc_stock_valuation(date, text, text) to service_role;
grant execute on function public.kfc_stock_ledger(date, date, text, text, text, text, integer, integer) to service_role;
grant execute on function public.kfc_stock_ageing(text) to service_role;
grant execute on function public.kfc_article_totals() to service_role;

-- ===== 0132_kfc_woo_stock_sync.sql =====
-- ============================================================================
-- 0132: KeyForCars ↔ WooCommerce stock push, and returns back into stock.
--
-- Stock push (CRM → shops). The CRM ledger is the master; the shops only show
-- what the warehouse can still sell (kfc_webshop_position.available: on the
-- shelves, minus order and job reservations, minus van stock).
--
--   kfc_woo_products        every product/variation a shop lists, with the
--                           article it maps to by SKU. status:
--                             ok         one article, shop manages stock → pushed
--                             unmapped   no article with this SKU
--                             ambiguous  SKU matches several articles, or the same
--                                        SKU is listed twice in one shop
--                             no_stock   the shop does not manage stock for it
--                           pushed_quantity/pushed_at/push_error: per-shop result.
--   kfc_woo_stock_outbox    one row per article whose sellable quantity may have
--                           changed. Filled by triggers (below) on every stock
--                           move, reservation and job reservation, so the POS,
--                           receipts, counts, returns and shipping all queue
--                           without touching their code. Only articles that a
--                           shop actually lists are queued, so an install with
--                           no shops (Autosleutel24) never fills it.
--   kfc_woo_sync_runs       one row per worker run per shop, for the status screen.
--
--   kfc_woo_enqueue(codes)  queue articles (manual "push now", "queue all").
--   kfc_woo_claim(n)        hand the worker up to n due articles; claimed rows
--                           are skipped by a parallel worker for 5 minutes.
--   kfc_woo_settle(...)     after a push: delete the row if nothing re-queued it
--                           meanwhile, else release it; on error back off
--                           1, 2, 4 … minutes, capped at 6 hours.
--   kfc_woo_release(codes)  give claimed rows back without counting an attempt.
--
-- Returns (shop → CRM).
--
--   kfc_shop_returns        one row per "Retour ontvangen": line, quantity,
--                           condition (new · opened · defect), where it went, the
--                           move(s) it booked, and the refund it answers (if any).
--   kfc_receive_return(...) books the return once per idempotency key: new and
--                           opened go to the chosen location (a shelf, or the
--                           quarantine location when it may not be sold), defect
--                           is booked into quarantine and written off in the same
--                           transaction ('correction'), so the line counts as
--                           returned and the value leaves stock traceably.
--                           Same shipped-minus-returned guard as 0113.
--
-- Server-only like 0090/0091: RLS on, no policies, nothing granted to anon or
-- authenticated; the Next.js server uses the service role. Idempotent.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Shop products and their article.
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_woo_products (
  shop             text not null,
  woo_product_id   bigint not null,
  woo_variation_id bigint not null default 0,   -- 0 = simple product
  sku              text not null default '',
  name             text not null default '',
  woo_type         text not null default 'simple',
  manage_stock     boolean not null default false,
  shop_quantity    integer,                     -- what the shop said at the last refresh
  article_code     text references public.kfc_articles (code) on delete set null,
  manual           boolean not null default false, -- article set by hand; a refresh keeps it
  status           text not null default 'unmapped' check (status in ('ok', 'unmapped', 'ambiguous', 'no_stock')),
  candidates       text[] not null default '{}', -- article codes when ambiguous
  pushed_quantity  integer,
  pushed_at        timestamptz,
  push_error       text,
  seen_at          timestamptz not null default now(),
  primary key (shop, woo_product_id, woo_variation_id)
);
create index if not exists kfc_woo_products_article_idx on public.kfc_woo_products (article_code) where article_code is not null;
create index if not exists kfc_woo_products_status_idx on public.kfc_woo_products (shop, status);

create table if not exists public.kfc_woo_stock_outbox (
  article_code    text primary key references public.kfc_articles (code) on delete cascade,
  queued_at       timestamptz not null default clock_timestamp(),
  next_attempt_at timestamptz not null default now(),
  claimed_until   timestamptz,
  attempts        integer not null default 0,
  last_error      text
);
create index if not exists kfc_woo_stock_outbox_due_idx on public.kfc_woo_stock_outbox (next_attempt_at);

create table if not exists public.kfc_woo_sync_runs (
  id          bigserial primary key,
  shop        text not null,
  kind        text not null check (kind in ('push', 'dry_run', 'mapping')),
  started_at  timestamptz not null default now(),
  finished_at timestamptz,
  articles    integer not null default 0,
  updated     integer not null default 0,
  failed      integer not null default 0,
  error       text,
  detail      jsonb
);
create index if not exists kfc_woo_sync_runs_shop_idx on public.kfc_woo_sync_runs (shop, started_at desc);

-- ---------------------------------------------------------------------------
-- Outbox functions.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_woo_enqueue(p_articles text[])
returns integer language plpgsql as $$
declare v_n integer;
begin
  insert into public.kfc_woo_stock_outbox (article_code)
  select distinct a.code from public.kfc_articles a
   where a.code = any (p_articles)
     and exists (select 1 from public.kfc_woo_products p where p.article_code = a.code)
  on conflict (article_code) do update
     set queued_at = clock_timestamp(), next_attempt_at = now(), attempts = 0, last_error = null;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- Row trigger shared by the ledger tables. Cheap: one indexed exists() and one upsert.
create or replace function public.kfc_woo_queue_article() returns trigger language plpgsql as $$
declare v_article text;
begin
  if tg_op = 'DELETE' then v_article := old.article_code; else v_article := new.article_code; end if;
  if v_article is not null and exists (select 1 from public.kfc_woo_products where article_code = v_article) then
    insert into public.kfc_woo_stock_outbox (article_code) values (v_article)
    on conflict (article_code) do update
       set queued_at = clock_timestamp(), next_attempt_at = now(), attempts = 0, last_error = null;
  end if;
  if tg_op = 'UPDATE' then
    if old.article_code is distinct from new.article_code and old.article_code is not null
       and exists (select 1 from public.kfc_woo_products where article_code = old.article_code) then
      insert into public.kfc_woo_stock_outbox (article_code) values (old.article_code)
      on conflict (article_code) do update
         set queued_at = clock_timestamp(), next_attempt_at = now(), attempts = 0, last_error = null;
    end if;
  end if;
  return null;
end $$;

drop trigger if exists kfc_woo_queue_moves on public.kfc_stock_moves;
create trigger kfc_woo_queue_moves after insert on public.kfc_stock_moves
  for each row execute function public.kfc_woo_queue_article();

drop trigger if exists kfc_woo_queue_reservations on public.kfc_reservations;
create trigger kfc_woo_queue_reservations after insert on public.kfc_reservations
  for each row execute function public.kfc_woo_queue_article();

-- Job reservations (0115) compete for the same stock; only when that table exists.
do $$
begin
  if to_regclass('public.kfc_job_stock') is not null then
    execute 'drop trigger if exists kfc_woo_queue_job_stock on public.kfc_job_stock';
    execute 'create trigger kfc_woo_queue_job_stock after insert or update or delete on public.kfc_job_stock
               for each row execute function public.kfc_woo_queue_article()';
  end if;
end $$;

-- Up to p_limit due, unclaimed articles; claims them for 5 minutes.
create or replace function public.kfc_woo_claim(p_limit integer default 200)
returns table (article_code text, queued_at timestamptz, attempts integer) language plpgsql as $$
#variable_conflict use_column
begin
  return query
  with due as (
    select o.article_code as code from public.kfc_woo_stock_outbox o
     where o.next_attempt_at <= now() and (o.claimed_until is null or o.claimed_until < now())
     order by o.next_attempt_at, o.queued_at
     limit greatest(1, least(coalesce(p_limit, 200), 1000))
     for update skip locked
  )
  update public.kfc_woo_stock_outbox o set claimed_until = now() + interval '5 minutes'
    from due where o.article_code = due.code
  returning o.article_code, o.queued_at, o.attempts;
end $$;

-- After a push attempt. p_error null = success.
create or replace function public.kfc_woo_settle(p_article text, p_queued_at timestamptz, p_error text default null)
returns void language plpgsql as $$
begin
  if p_error is null then
    delete from public.kfc_woo_stock_outbox where article_code = p_article and queued_at = p_queued_at;
    update public.kfc_woo_stock_outbox set claimed_until = null where article_code = p_article;
  else
    update public.kfc_woo_stock_outbox
       set claimed_until = null,
           attempts = attempts + 1,
           last_error = left(p_error, 500),
           next_attempt_at = now() + least(interval '6 hours', interval '1 minute' * power(2, least(attempts, 9)))
     where article_code = p_article;
  end if;
end $$;

create or replace function public.kfc_woo_release(p_articles text[])
returns void language sql as $$
  update public.kfc_woo_stock_outbox set claimed_until = null where article_code = any (p_articles);
$$;

-- ---------------------------------------------------------------------------
-- Returns.
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_shop_returns (
  id               uuid primary key default gen_random_uuid(),
  order_id         uuid not null references public.kfc_shop_orders (id) on delete cascade,
  order_line_id    uuid not null references public.kfc_shop_order_lines (id) on delete cascade,
  refund_id        uuid references public.kfc_shop_order_refunds (id) on delete set null,
  article_code     text not null references public.kfc_articles (code),
  quantity         integer not null check (quantity > 0),
  condition        text not null check (condition in ('new', 'opened', 'defect')),
  location_id      uuid references public.kfc_locations (id),
  return_move_id   bigint references public.kfc_stock_moves (id),
  writeoff_move_id bigint references public.kfc_stock_moves (id),
  scan             text,
  note             text,
  created_by       uuid,
  created_at       timestamptz not null default now(),
  idempotency_key  text not null unique
);
create index if not exists kfc_shop_returns_order_idx on public.kfc_shop_returns (order_id);
create index if not exists kfc_shop_returns_line_idx on public.kfc_shop_returns (order_line_id);

create or replace function public.kfc_receive_return(
  p_line uuid, p_quantity integer, p_condition text, p_location uuid, p_key text,
  p_created_by uuid default null, p_refund uuid default null, p_scan text default null, p_note text default null
) returns public.kfc_shop_returns language plpgsql as $$
declare
  v_row public.kfc_shop_returns; v_line public.kfc_shop_order_lines; v_shipped integer; v_returned integer;
  v_cost integer; v_target uuid; v_move public.kfc_stock_moves; v_off public.kfc_stock_moves; v_note text;
begin
  select * into v_row from public.kfc_shop_returns where idempotency_key = p_key;
  if found then return v_row; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  if p_condition is null or p_condition not in ('new', 'opened', 'defect') then raise exception 'KFC_BAD_CONDITION'; end if;

  select * into v_line from public.kfc_shop_order_lines where id = p_line for update;
  if not found then raise exception 'KFC_NO_ORDER_LINE'; end if;
  if v_line.article_code is null then raise exception 'KFC_LINE_UNMAPPED'; end if;
  if p_refund is not null and not exists (
    select 1 from public.kfc_shop_order_refunds where id = p_refund and order_id = v_line.order_id
  ) then raise exception 'KFC_BAD_REFUND'; end if;

  select coalesce(-sum(delta), 0), max(unit_cost_cents) into v_shipped, v_cost
    from public.kfc_stock_moves where order_line_id = p_line and reason = 'sale';
  select coalesce(sum(delta), 0) into v_returned
    from public.kfc_stock_moves where order_line_id = p_line and reason = 'return';
  if v_shipped = 0 then raise exception 'KFC_NOT_SHIPPED'; end if;
  if v_returned + p_quantity > v_shipped then raise exception 'KFC_RETURN_EXCEEDS'; end if;

  if p_condition = 'defect' then
    select id into v_target from public.kfc_locations
     where kind = 'quarantine' and technician_id is null order by (warehouse = 'main') desc, created_at limit 1;
    if v_target is null then raise exception 'KFC_LOCATION_REQUIRED'; end if;
  else
    if p_location is null or not exists (
      select 1 from public.kfc_locations where id = p_location and technician_id is null
    ) then raise exception 'KFC_LOCATION_REQUIRED'; end if;
    v_target := p_location;
  end if;

  v_note := left(concat_ws(' · ',
    'Retour (' || case p_condition when 'new' then 'nieuw' when 'opened' then 'geopend' else 'defect' end || ')',
    nullif(trim(p_note), '')), 500);
  v_move := public.kfc_book_move(v_line.article_code, v_target, p_quantity, 'return', p_key || ':return',
    v_cost, v_note, null, p_created_by, p_line);
  if p_condition = 'defect' then
    v_off := public.kfc_book_move(v_line.article_code, v_target, -p_quantity, 'correction', p_key || ':writeoff',
      v_cost, 'Afgeschreven: defecte retour', null, p_created_by);
  end if;

  insert into public.kfc_shop_returns (order_id, order_line_id, refund_id, article_code, quantity, condition,
    location_id, return_move_id, writeoff_move_id, scan, note, created_by, idempotency_key)
  values (v_line.order_id, p_line, p_refund, v_line.article_code, p_quantity, p_condition,
    v_target, v_move.id, v_off.id, left(p_scan, 80), left(nullif(trim(p_note), ''), 500), p_created_by, p_key)
  returning * into v_row;
  return v_row;
exception when unique_violation then
  -- A parallel request with the same key won the race; everything above rolled back.
  select * into v_row from public.kfc_shop_returns where idempotency_key = p_key;
  if found then return v_row; end if;
  raise;
end $$;

-- ---------------------------------------------------------------------------
-- Security: server-only.
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['kfc_woo_products', 'kfc_woo_stock_outbox', 'kfc_woo_sync_runs', 'kfc_shop_returns'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on public.%I to service_role', t);
  end loop;
end $$;
revoke all on sequence public.kfc_woo_sync_runs_id_seq from public, anon, authenticated;
grant usage, select on sequence public.kfc_woo_sync_runs_id_seq to service_role;

revoke all on function public.kfc_woo_enqueue(text[]) from public, anon, authenticated;
revoke all on function public.kfc_woo_queue_article() from public, anon, authenticated;
revoke all on function public.kfc_woo_claim(integer) from public, anon, authenticated;
revoke all on function public.kfc_woo_settle(text, timestamptz, text) from public, anon, authenticated;
revoke all on function public.kfc_woo_release(text[]) from public, anon, authenticated;
revoke all on function public.kfc_receive_return(uuid, integer, text, uuid, text, uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.kfc_woo_enqueue(text[]) to service_role;
grant execute on function public.kfc_woo_claim(integer) to service_role;
grant execute on function public.kfc_woo_settle(text, timestamptz, text) to service_role;
grant execute on function public.kfc_woo_release(text[]) to service_role;
grant execute on function public.kfc_receive_return(uuid, integer, text, uuid, text, uuid, uuid, text, text) to service_role;

-- ===== 0133_install_marker.sql =====
-- 0133: which install a database belongs to.
--
-- Autosleutel24 and KeyForCars run the same code on two Supabase projects. The
-- app already refuses a project ref that does not match CRM_INSTALL
-- (src/lib/supabase/installGuard.ts). This is the second lock, inside the
-- database itself: a one-row table naming the install, read by the app at
-- start and every few minutes through crm_install_profile().
--
-- This migration deliberately inserts NOTHING. The same file runs on both
-- databases, so the value is set by hand, once per database, as the runbook
-- (docs/keyforcars-installatie.md) says:
--   KeyForCars    (lzdwxkhlscsitstxdgar): insert into public.crm_install (profile) values ('keyforcars');
--   Autosleutel24 (utctfircycpjmpjqmtmm): insert into public.crm_install (profile) values ('autosleutel24');
-- Without a row the app runs as before (unless CRM_REQUIRE_INSTALL_MARKER=1).
--
-- Additive and idempotent.

create table if not exists public.crm_install (
  -- Always true: the primary key makes a second row impossible.
  singleton boolean primary key default true check (singleton),
  profile text not null check (profile in ('autosleutel24', 'keyforcars')),
  set_at timestamptz not null default now()
);

comment on table public.crm_install is
  'One row: which CRM install (CRM_INSTALL) this database belongs to. Set by hand per database; see docs/keyforcars-installatie.md.';

-- No policies: nobody reads or writes the table through the API. The app reads
-- it only through the function below.
alter table public.crm_install enable row level security;
revoke all on public.crm_install from anon, authenticated;

-- The profile name only ('keyforcars' / 'autosleutel24' / null). Callable with
-- the anon key because the guard runs before anyone is signed in; it reveals
-- nothing a visitor could not already guess from the domain.
create or replace function public.crm_install_profile()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select profile from public.crm_install where singleton;
$$;

revoke all on function public.crm_install_profile() from public;
grant execute on function public.crm_install_profile() to anon, authenticated, service_role;

-- ===== 0134_kfc_product_master.sql =====
-- ============================================================================
-- 0134: KeyForCars product master data (ERPNext "Item Group" style).
--
--   kfc_categories           category tree: parent, name, sort, default VAT rate,
--                            default margin. kfc_articles.category_id points here;
--                            kfc_articles.category (free text) is kept and always
--                            mirrors the leaf name, so older code keeps working.
--   kfc_category_aliases     old names that were merged into another category; a
--                            later write of the old text lands on the survivor
--                            instead of re-creating the merged category.
--   kfc_article_specs        one row per article: key type, frequency, chip,
--                            buttons, blade, vehicle brand.
--   kfc_article_fitments     make / model / year range the article fits.
--   kfc_article_changes      audit trail of bulk edits and imports (old → new).
--   kfc_barcode_duplicates   view: a barcode on more than one quantity-tracked
--                            article. Reported, never deleted; new duplicates are
--                            refused by the bulk editor and the import.
--   kfc_article_quality      view: one row per article with data-quality flags.
--   kfc_import_runs          (0091) also records article imports now: kind
--                            'article_import', a checksum per file + options, so
--                            the same file applied twice changes nothing.
--
-- RPCs: kfc_category_resolve (path → id, creates missing levels),
-- kfc_merge_categories, kfc_bulk_update_articles, kfc_apply_article_import.
--
-- Server-only like the rest of kfc_*: RLS on, no policies, nothing granted to
-- anon or authenticated; functions executable by service_role only. Idempotent.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Category tree
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_categories (
  id                  uuid primary key default gen_random_uuid(),
  parent_id           uuid references public.kfc_categories (id) on delete restrict,
  name                text not null check (length(btrim(name)) between 1 and 80 and name !~ '[>›]'),
  sort                integer not null default 0,
  vat_rate            numeric(5,2) not null default 21 check (vat_rate >= 0 and vat_rate <= 100),
  default_margin_pct  numeric(7,2) check (default_margin_pct is null or (default_margin_pct > -100 and default_margin_pct < 10000)),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create unique index if not exists kfc_categories_sibling_name
  on public.kfc_categories (coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(btrim(name)));
create index if not exists kfc_categories_parent_idx on public.kfc_categories (parent_id);

create table if not exists public.kfc_category_aliases (
  alias        text primary key,             -- lower(btrim(old name))
  category_id  uuid not null references public.kfc_categories (id) on delete cascade,
  created_at   timestamptz not null default now()
);

-- A category may never become its own ancestor.
create or replace function public.kfc_categories_guard()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.name := btrim(new.name);
  if new.parent_id is not null and (tg_op = 'INSERT' or new.parent_id is distinct from old.parent_id) then
    if new.parent_id = new.id or exists (
      with recursive up as (
        select id, parent_id from public.kfc_categories where id = new.parent_id
        union all
        select c.id, c.parent_id from public.kfc_categories c join up on c.id = up.parent_id
      ) select 1 from up where up.id = new.id
    ) then raise exception 'KFC_CATEGORY_CYCLE'; end if;
  end if;
  return new;
end $$;
drop trigger if exists kfc_categories_guard on public.kfc_categories;
create trigger kfc_categories_guard before insert or update of parent_id, name on public.kfc_categories
  for each row execute function public.kfc_categories_guard();

-- Full path per category ("Sleutels › Volkswagen › Golf"), for lists and exports.
create or replace view public.kfc_category_paths as
with recursive tree as (
  select id, parent_id, name, sort, 0 as depth, name::text as path, array[sort]::integer[] as sort_path, array[lower(name)] as name_path
    from public.kfc_categories where parent_id is null
  union all
  select c.id, c.parent_id, c.name, c.sort, t.depth + 1, t.path || ' › ' || c.name, t.sort_path || c.sort, t.name_path || lower(c.name)
    from public.kfc_categories c join tree t on c.parent_id = t.id
  where t.depth < 12
)
select id, parent_id, name, depth, path, sort_path, name_path from tree;

-- ---------------------------------------------------------------------------
-- Article columns
-- ---------------------------------------------------------------------------
alter table public.kfc_articles add column if not exists category_id uuid;
alter table public.kfc_articles add column if not exists min_stock integer;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'kfc_articles_category_fk') then
    alter table public.kfc_articles add constraint kfc_articles_category_fk
      foreign key (category_id) references public.kfc_categories (id) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'kfc_articles_min_stock_check') then
    alter table public.kfc_articles add constraint kfc_articles_min_stock_check check (min_stock is null or min_stock >= 0);
  end if;
end $$;
create index if not exists kfc_articles_category_idx on public.kfc_articles (category_id);
create index if not exists kfc_articles_ean_gin on public.kfc_articles using gin (ean);

-- Free text → category: alias first, then a root with that name, then any
-- category with that name, otherwise a new root category.
create or replace function public.kfc_category_for_text(p_text text)
returns uuid language plpgsql set search_path = '' as $$
declare v_name text := left(btrim(regexp_replace(coalesce(p_text, ''), '[>›]', '-', 'g')), 80); v_id uuid;
begin
  if v_name = '' then return null; end if;
  select category_id into v_id from public.kfc_category_aliases where alias = lower(v_name);
  if found then return v_id; end if;
  select id into v_id from public.kfc_categories where lower(name) = lower(v_name)
    order by (parent_id is null) desc, sort, created_at limit 1;
  if found then return v_id; end if;
  insert into public.kfc_categories (name) values (v_name) on conflict do nothing returning id into v_id;
  if v_id is null then
    select id into v_id from public.kfc_categories where parent_id is null and lower(name) = lower(v_name);
  end if;
  return v_id;
end $$;

-- category_id is the master; the text column mirrors its name. A write that
-- only sets the text (older RPCs, Woo import, quick article) is linked to the
-- tree by kfc_category_for_text.
create or replace function public.kfc_articles_category_sync()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.category_id is not null and (tg_op = 'INSERT' or new.category_id is distinct from old.category_id) then
    select name into new.category from public.kfc_categories where id = new.category_id;
  elsif tg_op = 'UPDATE' and new.category_id is null and old.category_id is not null
        and new.category is not distinct from old.category then
    new.category := '';
  elsif tg_op = 'INSERT' or new.category is distinct from old.category then
    if btrim(coalesce(new.category, '')) = '' then
      new.category := '';
      new.category_id := null;
    elsif new.category_id is null or not exists (
      select 1 from public.kfc_categories where id = new.category_id and lower(name) = lower(btrim(new.category))
    ) then
      new.category_id := public.kfc_category_for_text(new.category);
      select name into new.category from public.kfc_categories where id = new.category_id;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists kfc_articles_category_sync on public.kfc_articles;
create trigger kfc_articles_category_sync before insert or update of category, category_id on public.kfc_articles
  for each row execute function public.kfc_articles_category_sync();

-- A renamed category renames the text on its articles.
create or replace function public.kfc_categories_rename()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.name is distinct from old.name then
    update public.kfc_articles set category = new.name where category_id = new.id;
  end if;
  return null;
end $$;
drop trigger if exists kfc_categories_rename on public.kfc_categories;
create trigger kfc_categories_rename after update of name on public.kfc_categories
  for each row execute function public.kfc_categories_rename();

-- Backfill: one root category per distinct text category, then link. Odd
-- texts (">" in them, over 80 characters) go through the same resolver.
update public.kfc_articles set category_id = public.kfc_category_for_text(category)
 where category_id is null and btrim(category) <> '';

-- Path → id ("Sleutels > Volkswagen"); creates the missing levels.
create or replace function public.kfc_category_resolve(p_path text, p_create boolean default true)
returns uuid language plpgsql set search_path = '' as $$
declare v_part text; v_parent uuid := null; v_id uuid; v_first boolean := true;
begin
  if btrim(coalesce(p_path, '')) = '' then return null; end if;
  foreach v_part in array regexp_split_to_array(p_path, '\s*[>›]\s*') loop
    v_part := left(btrim(v_part), 80);
    continue when v_part = '';
    v_id := null;
    select id into v_id from public.kfc_categories
     where coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(v_parent, '00000000-0000-0000-0000-000000000000'::uuid)
       and lower(name) = lower(v_part);
    if v_id is null and v_first then
      select category_id into v_id from public.kfc_category_aliases where alias = lower(v_part);
    end if;
    if v_id is null then
      if not p_create then return null; end if;
      insert into public.kfc_categories (parent_id, name) values (v_parent, v_part) returning id into v_id;
    end if;
    v_parent := v_id;
    v_first := false;
  end loop;
  return v_parent;
end $$;

-- Merge p_from into p_into: articles move, children move (same-named children
-- merge recursively), the old name becomes an alias, p_from is deleted.
create or replace function public.kfc_merge_categories(p_from uuid, p_into uuid)
returns integer language plpgsql set search_path = '' as $$
declare v_from public.kfc_categories; v_child record; v_twin uuid; v_moved integer := 0; v_n integer;
begin
  if p_from = p_into then raise exception 'KFC_MERGE_SELF'; end if;
  select * into v_from from public.kfc_categories where id = p_from for update;
  if not found or not exists (select 1 from public.kfc_categories where id = p_into) then raise exception 'KFC_NO_CATEGORY'; end if;
  if exists (
    with recursive up as (
      select id, parent_id from public.kfc_categories where id = p_into
      union all select c.id, c.parent_id from public.kfc_categories c join up on c.id = up.parent_id
    ) select 1 from up where up.id = p_from
  ) then raise exception 'KFC_MERGE_INTO_CHILD'; end if;

  update public.kfc_articles set category_id = p_into, updated_at = now() where category_id = p_from;
  get diagnostics v_moved = row_count;

  for v_child in select id, name from public.kfc_categories where parent_id = p_from loop
    v_twin := null;
    select id into v_twin from public.kfc_categories where parent_id = p_into and lower(name) = lower(v_child.name);
    if v_twin is not null then
      v_n := public.kfc_merge_categories(v_child.id, v_twin);
      v_moved := v_moved + v_n;
    else
      update public.kfc_categories set parent_id = p_into, updated_at = now() where id = v_child.id;
    end if;
  end loop;

  update public.kfc_category_aliases set category_id = p_into where category_id = p_from;
  insert into public.kfc_category_aliases (alias, category_id) values (lower(v_from.name), p_into)
    on conflict (alias) do update set category_id = excluded.category_id;
  delete from public.kfc_categories where id = p_from;
  return v_moved;
end $$;

-- ---------------------------------------------------------------------------
-- Item attributes: specs (1:1) and vehicle fitments (1:n)
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_article_specs (
  article_code  text primary key references public.kfc_articles (code) on delete cascade,
  brand         text,                     -- vehicle brand the article is for (Volkswagen, Kawasaki …)
  key_type      text check (key_type is null or key_type in
                  ('remote', 'smart', 'flip', 'transponder', 'blade', 'emergency', 'housing', 'card', 'chip', 'pcb', 'battery', 'tool', 'other')),
  frequency     text,                     -- "433 MHz", "868 MHz", "125 kHz"
  chip          text,                     -- "ID48", "Hitag AES", "4D63"
  buttons       smallint check (buttons is null or buttons between 0 and 12),
  blade         text,                     -- blade profile, e.g. HU66
  updated_at    timestamptz not null default now()
);

create table if not exists public.kfc_article_fitments (
  id            uuid primary key default gen_random_uuid(),
  article_code  text not null references public.kfc_articles (code) on delete cascade,
  make          text not null check (length(btrim(make)) between 1 and 60),
  model         text not null default '',
  year_from     smallint check (year_from is null or year_from between 1950 and 2100),
  year_to       smallint check (year_to is null or year_to between 1950 and 2100),
  note          text,
  source        text not null default 'manual' check (source in ('manual', 'import', 'profile')),
  created_at    timestamptz not null default now(),
  constraint kfc_article_fitments_years check (year_to is null or year_from is null or year_to >= year_from)
);
create unique index if not exists kfc_article_fitments_unique
  on public.kfc_article_fitments (article_code, lower(make), lower(model), coalesce(year_from, 0), coalesce(year_to, 0));
create index if not exists kfc_article_fitments_vehicle_idx on public.kfc_article_fitments (lower(make), lower(model));

-- ---------------------------------------------------------------------------
-- Audit of bulk edits and imports
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_article_changes (
  id             bigserial primary key,
  article_code   text not null references public.kfc_articles (code) on delete cascade,
  source         text not null check (source in ('bulk', 'import')),
  changes        jsonb not null,          -- {"field": [old, new]}
  import_run_id  bigint,
  created_by     uuid,
  created_at     timestamptz not null default now()
);
create index if not exists kfc_article_changes_article_idx on public.kfc_article_changes (article_code, created_at desc);

-- ---------------------------------------------------------------------------
-- Barcodes and data quality
-- ---------------------------------------------------------------------------
create or replace view public.kfc_barcode_duplicates as
select b.barcode, array_agg(distinct b.code order by b.code) as codes, count(distinct b.code)::integer as articles
  -- Serial-tracked (used) articles share the barcode of the new product on purpose.
  from (select code, btrim(unnest(ean)) as barcode from public.kfc_articles where tracking = 'quantity') b
 where b.barcode <> ''
 group by b.barcode
having count(distinct b.code) > 1;

create or replace view public.kfc_article_quality as
with dup as (
  select distinct unnest(codes) as code from public.kfc_barcode_duplicates
), neg as (
  select distinct article_code as code from public.kfc_stock_levels where quantity < 0
)
select a.code, a.name, a.sku, a.status, a.category_id, a.ean,
       a.sale_price_cents, a.purchase_price_cents, a.min_stock, a.supplier_ref, a.tracking, a.condition,
       coalesce(p.physical, 0) as physical,
       (a.status <> 'discontinued' and cardinality(array_remove(a.ean, '')) = 0)          as no_barcode,
       (a.category_id is null)                                                             as no_category,
       (a.status <> 'discontinued' and coalesce(a.sale_price_cents, 0) = 0)                as no_price,
       (a.status <> 'discontinued' and a.purchase_price_cents is null)                     as no_purchase_price,
       (d.code is not null)                                                                as duplicate_barcode,
       (n.code is not null or coalesce(p.physical, 0) < 0)                                 as negative_stock
  from public.kfc_articles a
  left join public.kfc_stock_position p on p.article_code = a.code
  left join dup d on d.code = a.code
  left join neg n on n.code = a.code;

-- ---------------------------------------------------------------------------
-- One article change: {before:{field:value}} must still match the row
-- (someone may have changed it meanwhile), {after:{field:value}} is written.
-- New barcodes may not belong to another article. Returns 'updated',
-- 'unchanged', 'conflict' or 'missing'.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_article_fields()
returns text[] language sql immutable set search_path = '' as $$
  select array['name', 'sku', 'ean', 'category_id', 'status', 'sale_price_cents', 'purchase_price_cents', 'min_stock', 'supplier_ref']
$$;

create or replace function public.kfc_apply_article_change(
  p_code text, p_before jsonb, p_after jsonb, p_source text, p_run bigint, p_user uuid
) returns text language plpgsql set search_path = '' as $$
declare
  v_row public.kfc_articles; v_new public.kfc_articles; v_old jsonb; v_key text; v_diff jsonb := '{}'::jsonb; v_bar text;
begin
  select * into v_row from public.kfc_articles where code = p_code for update;
  if not found then return 'missing'; end if;
  v_old := to_jsonb(v_row);
  for v_key in select jsonb_object_keys(coalesce(p_before, '{}'::jsonb) || coalesce(p_after, '{}'::jsonb)) loop
    if not v_key = any(public.kfc_article_fields()) then raise exception 'KFC_BAD_FIELD:%', v_key; end if;
  end loop;
  for v_key in select jsonb_object_keys(coalesce(p_before, '{}'::jsonb)) loop
    if (v_old -> v_key) is distinct from (p_before -> v_key) then return 'conflict'; end if;
  end loop;
  v_new := jsonb_populate_record(v_row, coalesce(p_after, '{}'::jsonb));
  if v_new.ean is distinct from v_row.ean then
    select coalesce(array_agg(distinct btrim(e)), '{}') into v_new.ean from unnest(v_new.ean) e where btrim(e) <> '';
    foreach v_bar in array v_new.ean loop
      if v_row.tracking = 'quantity' and not v_bar = any(v_row.ean) and exists (
        select 1 from public.kfc_articles where code <> p_code and tracking = 'quantity' and v_bar = any(ean)
      ) then raise exception 'KFC_DUPLICATE_BARCODE:%', v_bar; end if;
    end loop;
  end if;
  for v_key in select unnest(public.kfc_article_fields()) loop
    if (v_old -> v_key) is distinct from (to_jsonb(v_new) -> v_key) then
      v_diff := v_diff || jsonb_build_object(v_key, jsonb_build_array(v_old -> v_key, to_jsonb(v_new) -> v_key));
    end if;
  end loop;
  if v_diff = '{}'::jsonb then return 'unchanged'; end if;
  update public.kfc_articles set
    name = v_new.name, sku = v_new.sku, ean = v_new.ean, category_id = v_new.category_id, status = v_new.status,
    sale_price_cents = v_new.sale_price_cents, purchase_price_cents = v_new.purchase_price_cents,
    min_stock = v_new.min_stock, supplier_ref = v_new.supplier_ref, updated_at = now()
  where code = p_code;
  insert into public.kfc_article_changes (article_code, source, changes, import_run_id, created_by)
  values (p_code, p_source, v_diff, p_run, p_user);
  return 'updated';
end $$;

-- Bulk edit: [{code, before, after}]. All or nothing: one conflict and the
-- whole call is rolled back with the conflicting codes in the message.
create or replace function public.kfc_bulk_update_articles(p_changes jsonb, p_user uuid default null)
returns jsonb language plpgsql set search_path = '' as $$
declare v_item jsonb; v_result text; v_conflicts text[] := '{}'; v_updated integer := 0;
begin
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) > 5000 then raise exception 'KFC_BAD_BATCH'; end if;
  for v_item in select * from jsonb_array_elements(p_changes) loop
    v_result := public.kfc_apply_article_change(v_item ->> 'code', v_item -> 'before', v_item -> 'after', 'bulk', null, p_user);
    if v_result in ('conflict', 'missing') then v_conflicts := v_conflicts || (v_item ->> 'code'); end if;
    if v_result = 'updated' then v_updated := v_updated + 1; end if;
  end loop;
  if cardinality(v_conflicts) > 0 then
    raise exception 'KFC_CONFLICT:%', array_to_string(v_conflicts, ',');
  end if;
  return jsonb_build_object('updated', v_updated);
end $$;

-- ---------------------------------------------------------------------------
-- Import runs: article imports share kfc_import_runs with the Woo importer.
-- The kind check is widened by OR-ing onto whatever the current check is, so a
-- kind another migration added is never lost.
-- ---------------------------------------------------------------------------
alter table public.kfc_import_runs add column if not exists checksum   text;
alter table public.kfc_import_runs add column if not exists file_name  text;
alter table public.kfc_import_runs add column if not exists summary    jsonb;
alter table public.kfc_import_runs add column if not exists created_by uuid;
do $$
declare v_name text; v_def text;
begin
  select conname, pg_get_constraintdef(oid) into v_name, v_def from pg_constraint
   where conrelid = 'public.kfc_import_runs'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%kind%'
   limit 1;
  if v_name is not null and v_def not ilike '%article_import%' then
    execute format('alter table public.kfc_import_runs drop constraint %I', v_name);
    execute format('alter table public.kfc_import_runs add constraint %I check (%s or kind = %L)',
      v_name, regexp_replace(v_def, '^CHECK\s*', ''), 'article_import');
  end if;
end $$;
create unique index if not exists kfc_import_runs_article_checksum
  on public.kfc_import_runs (checksum) where kind = 'article_import' and error is null;

-- p_rows: [{action:'create'|'update', code?, before?, after:{…}, category_path?, specs?, fitments?}]
-- prepared by the server from the same file it showed in the dry run. All or
-- nothing; a file already applied (same checksum) returns that run unchanged.
create or replace function public.kfc_apply_article_import(
  p_checksum text, p_file text, p_prefix text, p_rows jsonb, p_user uuid default null
) returns jsonb language plpgsql set search_path = '' as $$
declare
  v_run public.kfc_import_runs; v_row jsonb; v_after jsonb; v_code text; v_next bigint; v_result text;
  v_created integer := 0; v_updated integer := 0; v_unchanged integer := 0; v_fit jsonb; v_constraint text;
  v_conflicts text[] := '{}'; v_bar text; v_ean text[];
begin
  if p_prefix not in ('KFC-1-', 'AS24-1-') then raise exception 'KFC_BAD_PREFIX'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 20000 then raise exception 'KFC_BAD_BATCH'; end if;
  select * into v_run from public.kfc_import_runs where kind = 'article_import' and checksum = p_checksum and error is null;
  if found then return jsonb_build_object('replay', true, 'run', v_run.id, 'summary', v_run.summary, 'finished_at', v_run.finished_at); end if;

  insert into public.kfc_import_runs (shop, kind, checksum, file_name, created_by)
  values ('artikelen', 'article_import', p_checksum, left(p_file, 200), p_user) returning * into v_run;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_after := coalesce(v_row -> 'after', '{}'::jsonb);
    if coalesce(v_row ->> 'category_path', '') <> '' then
      v_after := v_after || jsonb_build_object('category_id', public.kfc_category_resolve(v_row ->> 'category_path', true));
    end if;
    if v_row ->> 'action' = 'create' then
      v_code := nullif(v_row ->> 'code', '');
      if v_code is null then
        perform pg_advisory_xact_lock(hashtext('kfc_article_code:' || p_prefix));
        select coalesce(max(substr(code, length(p_prefix) + 1)::bigint), 0) + 1 into v_next
          from public.kfc_articles where code ~ ('^' || p_prefix || '[0-9]{1,18}$');
        v_code := p_prefix || v_next::text;
      end if;
      select coalesce(array_agg(distinct btrim(e)), '{}') into v_ean
        from jsonb_array_elements_text(coalesce(v_after -> 'ean', '[]'::jsonb)) e where btrim(e) <> '';
      foreach v_bar in array v_ean loop
        if exists (select 1 from public.kfc_articles where tracking = 'quantity' and v_bar = any(ean)) then raise exception 'KFC_DUPLICATE_BARCODE:%', v_bar; end if;
      end loop;
      insert into public.kfc_articles (code, name, sku, ean, category_id, status, sale_price_cents, purchase_price_cents, min_stock, supplier_ref)
      values (v_code, coalesce(v_after ->> 'name', v_code), coalesce(v_after ->> 'sku', ''), v_ean,
              (v_after ->> 'category_id')::uuid, coalesce(v_after ->> 'status', 'held'),
              (v_after ->> 'sale_price_cents')::integer, (v_after ->> 'purchase_price_cents')::integer,
              (v_after ->> 'min_stock')::integer, nullif(v_after ->> 'supplier_ref', ''));
      insert into public.kfc_article_changes (article_code, source, changes, import_run_id, created_by)
      values (v_code, 'import', jsonb_build_object('created', jsonb_build_array(null, v_after)), v_run.id, p_user);
      v_created := v_created + 1;
    elsif v_row ->> 'action' = 'update' then
      v_code := v_row ->> 'code';
      v_result := public.kfc_apply_article_change(v_code, v_row -> 'before', v_after, 'import', v_run.id, p_user);
      if v_result in ('conflict', 'missing') then v_conflicts := v_conflicts || v_code; end if;
      if v_result = 'updated' then v_updated := v_updated + 1; else v_unchanged := v_unchanged + 1; end if;
    else
      continue;
    end if;

    if jsonb_typeof(v_row -> 'specs') = 'object' and v_row -> 'specs' <> '{}'::jsonb then
      insert into public.kfc_article_specs (article_code) values (v_code) on conflict do nothing;
      update public.kfc_article_specs s set
        brand     = coalesce(v_row -> 'specs' ->> 'brand', s.brand),
        key_type  = coalesce(v_row -> 'specs' ->> 'key_type', s.key_type),
        frequency = coalesce(v_row -> 'specs' ->> 'frequency', s.frequency),
        chip      = coalesce(v_row -> 'specs' ->> 'chip', s.chip),
        buttons   = coalesce((v_row -> 'specs' ->> 'buttons')::smallint, s.buttons),
        blade     = coalesce(v_row -> 'specs' ->> 'blade', s.blade),
        updated_at = now()
      where s.article_code = v_code;
    end if;
    for v_fit in select * from jsonb_array_elements(coalesce(v_row -> 'fitments', '[]'::jsonb)) loop
      insert into public.kfc_article_fitments (article_code, make, model, year_from, year_to, source)
      values (v_code, v_fit ->> 'make', coalesce(v_fit ->> 'model', ''), (v_fit ->> 'year_from')::smallint, (v_fit ->> 'year_to')::smallint, 'import')
      on conflict do nothing;
    end loop;
  end loop;

  if cardinality(v_conflicts) > 0 then raise exception 'KFC_CONFLICT:%', array_to_string(v_conflicts, ','); end if;

  update public.kfc_import_runs set finished_at = now(), orders = v_created + v_updated,
    summary = jsonb_build_object('created', v_created, 'updated', v_updated, 'unchanged', v_unchanged)
   where id = v_run.id returning * into v_run;
  return jsonb_build_object('replay', false, 'run', v_run.id, 'summary', v_run.summary, 'finished_at', v_run.finished_at);
exception when unique_violation then
  get stacked diagnostics v_constraint = constraint_name;
  if v_constraint = 'kfc_import_runs_article_checksum' then
    select * into v_run from public.kfc_import_runs where kind = 'article_import' and checksum = p_checksum and error is null;
    return jsonb_build_object('replay', true, 'run', v_run.id, 'summary', v_run.summary, 'finished_at', v_run.finished_at);
  end if;
  raise;
end $$;

-- ---------------------------------------------------------------------------
-- Security: server-only.
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['kfc_categories', 'kfc_category_aliases', 'kfc_article_specs', 'kfc_article_fitments', 'kfc_article_changes'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;
revoke all on public.kfc_category_paths, public.kfc_barcode_duplicates, public.kfc_article_quality from anon, authenticated;
revoke all on sequence public.kfc_article_changes_id_seq from anon, authenticated;

revoke all on function public.kfc_categories_guard() from public, anon, authenticated;
revoke all on function public.kfc_categories_rename() from public, anon, authenticated;
revoke all on function public.kfc_articles_category_sync() from public, anon, authenticated;
revoke all on function public.kfc_category_for_text(text) from public, anon, authenticated;
revoke all on function public.kfc_category_resolve(text, boolean) from public, anon, authenticated;
revoke all on function public.kfc_merge_categories(uuid, uuid) from public, anon, authenticated;
revoke all on function public.kfc_article_fields() from public, anon, authenticated;
revoke all on function public.kfc_apply_article_change(text, jsonb, jsonb, text, bigint, uuid) from public, anon, authenticated;
revoke all on function public.kfc_bulk_update_articles(jsonb, uuid) from public, anon, authenticated;
revoke all on function public.kfc_apply_article_import(text, text, text, jsonb, uuid) from public, anon, authenticated;
grant execute on function public.kfc_category_resolve(text, boolean) to service_role;
grant execute on function public.kfc_merge_categories(uuid, uuid) to service_role;
grant execute on function public.kfc_bulk_update_articles(jsonb, uuid) to service_role;
grant execute on function public.kfc_apply_article_import(text, text, text, jsonb, uuid) to service_role;
-- Called inside the triggers and RPCs above, which run as the caller (service_role).
grant execute on function public.kfc_category_for_text(text) to service_role;
grant execute on function public.kfc_article_fields() to service_role;
grant execute on function public.kfc_apply_article_change(text, jsonb, jsonb, text, bigint, uuid) to service_role;

-- ===== 0135_revoke_anon_execute.sql =====
/*
 * Close the anon key's EXECUTE on functions that were never meant for it.
 *
 * Postgres grants EXECUTE on every new function to PUBLIC, and Supabase's
 * anon role inherits that. The kfc_* functions revoke it explicitly, but the
 * older ones (0021, 0026, 0035, 0055, 0057, the stock_items helpers…) never
 * did, so anyone holding the public anon key — it ships in the browser — could
 * call them through /rest/v1/rpc. Found by a security scan on 21 Nov 2026,
 * confirmed with no-op calls on the KeyForCars database:
 *   crm_settle_payment        mark a job payment paid
 *   crm_respond_to_offer_*    accept/decline a technician's offer by phone/chat id
 *   crm_set_job_travel        set travel costs on a job
 *   apply_stock_delta         change old stock_items quantities
 *
 * What this does, per public function anon can execute today:
 *   - remembers whether authenticated and service_role can execute it,
 *   - revokes EXECUTE from PUBLIC and anon,
 *   - grants it back to authenticated / service_role exactly where they had it.
 * So logged-in users and the server keep every right they had; only the
 * anonymous key loses access.
 *
 * Left alone: crm_install_profile() (public on purpose, 0133), trigger
 * functions (they run as part of a table write, not via RPC), and any function
 * used inside an RLS policy (anon may need it while reading public tables).
 *
 * Idempotent: a second run finds nothing left to revoke.
 */
do $$
declare
  r record;
  v_auth boolean;
  v_service boolean;
  v_closed integer := 0;
begin
  for r in
    select p.oid, p.oid::regprocedure as sig, p.proname
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.prokind = 'f'
       and p.prorettype <> 'trigger'::regtype
       and p.proname <> 'crm_install_profile'
       and has_function_privilege('anon', p.oid, 'execute')
       and not exists (
         select 1 from pg_policies pol
          where pol.schemaname = 'public'
            and (coalesce(pol.qual, '') ~ ('\m' || p.proname || '\s*\(')
              or coalesce(pol.with_check, '') ~ ('\m' || p.proname || '\s*\('))
       )
  loop
    v_auth := has_function_privilege('authenticated', r.oid, 'execute');
    v_service := has_function_privilege('service_role', r.oid, 'execute');
    execute format('revoke execute on function %s from public, anon', r.sig);
    if v_auth then execute format('grant execute on function %s to authenticated', r.sig); end if;
    if v_service then execute format('grant execute on function %s to service_role', r.sig); end if;
    v_closed := v_closed + 1;
  end loop;
  raise notice '0135: closed anon EXECUTE on % functions', v_closed;
end
$$;

-- ===== 0136_kfc_pos_returns_cash.sql =====
/*
 * Kassa, part two: returns at the counter, cash in / out, closing per payment
 * method and a stored Z-report.
 *
 *   kfc_pos_return(...)     a counter return against the original till sale:
 *                           per invoice line at most sold − already returned
 *                           (the original invoice row is locked, so two returns
 *                           at once cannot over-return), the goods go back on a
 *                           location the cashier picks (shelf or quarantine, no
 *                           van) through kfc_book_move with reason 'return' at
 *                           the unit cost of the original sale move, the money
 *                           goes out as a negative payment in the cashier's open
 *                           session, and a credit invoice with negative lines is
 *                           written, linked by sales_invoices.credit_of_invoice_id.
 *   kfc_pos_cash_move(...)  petty cash / bank deposit: money into or out of the
 *                           drawer with a mandatory reason, only on an open session.
 *   kfc_pos_close(...)      now takes the counted cash AND the PIN terminal total;
 *                           expected, counted and difference are stored per method,
 *                           a gapless Z-number is allocated inside the closing
 *                           transaction and the closing figures are frozen in
 *                           kfc_pos_sessions.z_report (jsonb) for reprints.
 *   kfc_pos_sale(...)       same contract as 0129, but stock only leaves sellable
 *                           shelf locations (kind 'shelf', not a technician's van);
 *                           an optional per-line "location" must be one of those.
 *                           The incl.-VAT price per line is kept on the invoice line
 *                           (pos_unit_incl_cents), so refunds and reprints use the
 *                           exact cents the customer paid.
 *
 * Expected cash = opening float + cash sales − cash refunds + cash in − cash out.
 * Expected PIN  = PIN sales − PIN refunds.
 *
 * Unit cost of sales is NOT set here: migration 0137 stamps the moving average on
 * every outbound move. kfc_book_move is not changed.
 *
 * Server-only like 0129: RLS on, no policies, nothing for anon / authenticated.
 * Idempotent: if not exists / create or replace / drop … if exists throughout.
 */

-- ---------------------------------------------------------------------------
-- Columns
-- ---------------------------------------------------------------------------

alter table public.sales_invoices
  add column if not exists credit_of_invoice_id uuid references public.sales_invoices (id);
create index if not exists sales_invoices_credit_of on public.sales_invoices (credit_of_invoice_id) where credit_of_invoice_id is not null;

-- What the customer paid per unit and the discount, incl. VAT, in cents (till lines only).
alter table public.sales_invoice_lines
  add column if not exists pos_unit_incl_cents integer,
  add column if not exists pos_discount_incl_cents integer;

alter table public.kfc_pos_sessions
  add column if not exists expected_pin_cents    integer,
  add column if not exists counted_pin_cents     integer,
  add column if not exists cash_difference_cents integer,
  add column if not exists pin_difference_cents  integer,
  add column if not exists z_number              integer,
  add column if not exists z_report              jsonb;

alter table public.kfc_pos_sessions drop constraint if exists kfc_pos_sessions_counted_pin_check;
alter table public.kfc_pos_sessions add constraint kfc_pos_sessions_counted_pin_check
  check (counted_pin_cents is null or counted_pin_cents >= 0);
create unique index if not exists kfc_pos_sessions_z_number on public.kfc_pos_sessions (z_number) where z_number is not null;
create index if not exists kfc_pos_sessions_closed on public.kfc_pos_sessions (closed_at desc) where closed_at is not null;

-- Payments: a refund is a negative payment. The old "amount > 0" check goes; the
-- new one keeps it for sales and allows only a negative cash / PIN refund.
alter table public.kfc_pos_payments add column if not exists kind text not null default 'sale';
do $$
declare r record;
begin
  for r in select conname from pg_constraint
            where conrelid = 'public.kfc_pos_payments'::regclass and contype = 'c'
              and pg_get_constraintdef(oid) ilike '%amount_cents > 0%'
              and conname <> 'kfc_pos_payments_kind_amount'
  loop
    execute format('alter table public.kfc_pos_payments drop constraint %I', r.conname);
  end loop;
end $$;
alter table public.kfc_pos_payments drop constraint if exists kfc_pos_payments_kind_amount;
alter table public.kfc_pos_payments add constraint kfc_pos_payments_kind_amount check (
  (kind = 'sale' and amount_cents > 0)
  or (kind = 'refund' and amount_cents < 0 and tendered_cents = amount_cents and method in ('cash', 'pin'))
);

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.kfc_pos_cash_moves (
  id               bigserial primary key,
  session_id       uuid not null references public.kfc_pos_sessions (id),
  direction        text not null check (direction in ('in', 'out')),
  amount_cents     integer not null check (amount_cents > 0 and amount_cents <= 10000000),
  reason           text not null check (length(btrim(reason)) between 3 and 500),
  created_by       uuid,
  created_at       timestamptz not null default now(),
  idempotency_key  text not null unique
);
create index if not exists kfc_pos_cash_moves_session on public.kfc_pos_cash_moves (session_id);

create table if not exists public.kfc_pos_returns (
  id                   uuid primary key default gen_random_uuid(),
  session_id           uuid not null references public.kfc_pos_sessions (id),
  original_invoice_id  uuid not null references public.sales_invoices (id),
  credit_invoice_id    uuid not null unique references public.sales_invoices (id),
  method               text not null check (method in ('cash', 'pin')),
  refund_cents         integer not null check (refund_cents >= 0),
  location_id          uuid not null references public.kfc_locations (id),
  reason               text,
  created_by           uuid,
  created_at           timestamptz not null default now(),
  idempotency_key      text not null unique
);
create index if not exists kfc_pos_returns_original on public.kfc_pos_returns (original_invoice_id);
create index if not exists kfc_pos_returns_session on public.kfc_pos_returns (session_id);

create table if not exists public.kfc_pos_return_lines (
  id               bigserial primary key,
  return_id        uuid not null references public.kfc_pos_returns (id),
  invoice_line_id  uuid not null references public.sales_invoice_lines (id),
  article_code     text not null references public.kfc_articles (code),
  quantity         integer not null check (quantity > 0),
  refund_cents     integer not null check (refund_cents >= 0),
  unit_cost_cents  integer,
  stock_move_id    bigint references public.kfc_stock_moves (id)
);
create index if not exists kfc_pos_return_lines_line on public.kfc_pos_return_lines (invoice_line_id);
create index if not exists kfc_pos_return_lines_return on public.kfc_pos_return_lines (return_id);

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- What should be in the drawer and on the terminal right now.
create or replace function public.kfc_pos_expected(p_session uuid)
returns table (expected_cash_cents integer, expected_pin_cents integer)
language sql stable set search_path = public as $$
  select
    (s.opening_float_cents
      + coalesce((select sum(p.amount_cents) from public.kfc_pos_payments p where p.session_id = s.id and p.method = 'cash'), 0)
      + coalesce((select sum(case when m.direction = 'in' then m.amount_cents else -m.amount_cents end)
                    from public.kfc_pos_cash_moves m where m.session_id = s.id), 0))::integer,
    coalesce((select sum(p.amount_cents) from public.kfc_pos_payments p where p.session_id = s.id and p.method = 'pin'), 0)::integer
  from public.kfc_pos_sessions s where s.id = p_session
$$;

-- Incl.-VAT cents of one invoice line: exact for till lines, rebuilt from the
-- excl. prices for older lines.
create or replace function public.kfc_pos_line_incl(l public.sales_invoice_lines)
returns integer language sql immutable set search_path = public as $$
  select case
    when l.pos_unit_incl_cents is not null
      then (l.quantity * l.pos_unit_incl_cents - coalesce(l.pos_discount_incl_cents, 0))::integer
    else round((l.quantity * l.unit_price - l.discount) * (1 + l.vat_rate / 100) * 100)::integer
  end
$$;

-- ---------------------------------------------------------------------------
-- Sale: only from sellable shelf locations
-- ---------------------------------------------------------------------------
--
-- p_lines:    [{ "article": "AS24-1-...", "quantity": 2, "unit_price_cents": 1995,
--                "discount_cents": 0, "vat_rate": 21, "location": <uuid, optional> }, ...]
-- (prices incl. VAT; the server decides who may change them, see src/lib/kfcPos.ts)

create or replace function public.kfc_pos_sale(
  p_session uuid, p_key text, p_lines jsonb, p_payments jsonb,
  p_customer uuid, p_client_name text, p_biller jsonb, p_created_by uuid
) returns uuid language plpgsql set search_path = public as $$
declare
  v_invoice uuid; v_session public.kfc_pos_sessions;
  v_line jsonb; v_pay jsonb; v_i integer := 0;
  v_article public.kfc_articles; v_qty integer; v_price integer; v_disc integer; v_rate numeric;
  v_incl integer; v_total integer := 0; v_vat numeric := 0;
  v_cash integer := 0; v_noncash integer := 0; v_change integer;
  v_method text; v_tendered integer; v_location uuid; v_number text; v_loc_text text;
begin
  if p_key is null or length(p_key) < 8 or length(p_key) > 80 then raise exception 'KFC_POS_BAD_KEY'; end if;

  select id into v_invoice from public.sales_invoices where pos_key = p_key;
  if found then return v_invoice; end if;

  select * into v_session from public.kfc_pos_sessions where id = p_session for update;
  if not found or v_session.closed_at is not null then raise exception 'KFC_POS_CLOSED'; end if;

  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) = 0 or jsonb_array_length(p_lines) > 200 then
    raise exception 'KFC_POS_BAD_LINES';
  end if;
  if jsonb_typeof(p_payments) is distinct from 'array' or jsonb_array_length(p_payments) = 0 or jsonb_array_length(p_payments) > 10 then
    raise exception 'KFC_POS_BAD_PAYMENTS';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    if not found then raise exception 'KFC_POS_UNKNOWN_ARTICLE'; end if;
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    if v_qty is null or v_qty < 1 or v_qty > 10000 or v_price is null or v_price < 0 or v_price > 10000000
       or v_disc < 0 or v_disc > v_qty * v_price or v_rate not in (0, 9, 21) then
      raise exception 'KFC_POS_BAD_LINES';
    end if;
    v_loc_text := nullif(v_line->>'location', '');
    if v_loc_text is not null then
      if v_loc_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'KFC_POS_BAD_LINES'; end if;
      if not exists (select 1 from public.kfc_locations
                      where id = v_loc_text::uuid and kind = 'shelf' and technician_id is null) then
        raise exception 'KFC_POS_NOT_SELLABLE';
      end if;
    end if;
    v_incl := v_qty * v_price - v_disc;
    v_total := v_total + v_incl;
    v_vat := v_vat + v_incl - v_incl / (1 + v_rate / 100);
  end loop;

  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method is null or v_method not in ('cash', 'pin', 'other') or v_tendered is null or v_tendered <= 0 or v_tendered > 100000000 then
      raise exception 'KFC_POS_BAD_PAYMENTS';
    end if;
    if v_method = 'cash' then v_cash := v_cash + v_tendered; else v_noncash := v_noncash + v_tendered; end if;
  end loop;
  if v_noncash > v_total then raise exception 'KFC_POS_OVERPAID'; end if;
  if v_cash + v_noncash < v_total then raise exception 'KFC_POS_UNDERPAID'; end if;
  v_change := v_cash + v_noncash - v_total;

  insert into public.sales_invoices (
    biller_name, biller_street, biller_postcode, biller_city, biller_email, biller_phone, biller_kvk, biller_btw, biller_iban,
    client_name, notes, subtotal, vat_total, total, status, paid_at, created_by, customer_id, pos_session_id, pos_key
  ) values (
    coalesce(nullif(p_biller->>'name', ''), 'Winkel'), p_biller->>'street', p_biller->>'postcode', p_biller->>'city',
    p_biller->>'email', p_biller->>'phone', p_biller->>'kvk', p_biller->>'btw', p_biller->>'iban',
    coalesce(nullif(trim(coalesce(p_client_name, '')), ''), 'Kassaverkoop'), 'Kassa',
    round((v_total - round(v_vat)) / 100.0, 2), round(round(v_vat) / 100.0, 2), round(v_total / 100.0, 2),
    'betaald', now(), p_created_by, p_customer, p_session, p_key
  ) returning id, invoice_number into v_invoice, v_number;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_i := v_i + 1;
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    insert into public.sales_invoice_lines (invoice_id, line_no, description, quantity, unit_price, discount, vat_rate,
      pos_unit_incl_cents, pos_discount_incl_cents)
    values (v_invoice, v_i,
      left(v_article.name || case when v_article.sku <> '' then ' (' || v_article.sku || ')' else '' end, 300),
      v_qty, round(v_price / (1 + v_rate / 100) / 100.0, 2), round(v_disc / (1 + v_rate / 100) / 100.0, 2), v_rate,
      v_price, v_disc);

    -- The bin: the one the cashier named, else the sellable shelf holding the most.
    v_location := nullif(v_line->>'location', '')::uuid;
    if v_location is null then
      select l.location_id into v_location
        from public.kfc_stock_levels l
        join public.kfc_locations loc on loc.id = l.location_id
       where l.article_code = v_article.code and loc.kind = 'shelf' and loc.technician_id is null
       order by l.quantity desc, l.location_id
       limit 1;
      -- Located stock exists, but only in a van or quarantine: not for sale at the counter.
      if v_location is null and exists (select 1 from public.kfc_stock_levels where article_code = v_article.code) then
        raise exception 'KFC_POS_NOT_SELLABLE';
      end if;
    end if;
    perform public.kfc_book_move(v_article.code, v_location, -v_qty, 'sale', p_key || ':line:' || v_i,
      null, 'Kassa ' || v_number, null, p_created_by, null, null, null, v_invoice);
  end loop;

  v_i := 0;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_i := v_i + 1;
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method = 'cash' then
      if v_change >= v_tendered then v_change := v_change - v_tendered; continue; end if;
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, 'cash', v_tendered - v_change, v_tendered, p_created_by, p_key || ':pay:' || v_i);
      v_change := 0;
    else
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, v_method, v_tendered, v_tendered, p_created_by, p_key || ':pay:' || v_i);
    end if;
  end loop;

  if p_customer is not null and v_total > 0 then
    perform public.kfc_post_entry(p_customer, 'payment', v_total, p_key || ':ledger', null, 'Kassa ' || v_number,
      p_created_by, null, v_invoice);
  end if;

  return v_invoice;
end $$;

-- ---------------------------------------------------------------------------
-- Return at the counter
-- ---------------------------------------------------------------------------
--
-- p_lines: [{ "line_id": <sales_invoice_lines.id of the original>, "quantity": 1 }, ...]
-- Returns the credit invoice id. The same p_key again returns the first result.

create or replace function public.kfc_pos_return(
  p_session uuid, p_key text, p_invoice uuid, p_lines jsonb, p_method text,
  p_location uuid, p_reason text, p_created_by uuid
) returns uuid language plpgsql set search_path = public as $$
declare
  v_existing uuid; v_session public.kfc_pos_sessions; v_orig public.sales_invoices;
  v_req jsonb; v_line public.sales_invoice_lines; v_qty integer; v_line_text text;
  v_returned integer; v_sold integer; v_line_incl integer; v_refund_line integer; v_unit_incl integer;
  v_move public.kfc_stock_moves; v_sale_move public.kfc_stock_moves;
  v_credit uuid; v_number text; v_return uuid := gen_random_uuid();
  v_total integer := 0; v_vat numeric := 0; v_i integer := 0; v_drawer integer;
  v_seen uuid[] := '{}';
begin
  if p_key is null or length(p_key) < 8 or length(p_key) > 80 then raise exception 'KFC_POS_BAD_KEY'; end if;

  select credit_invoice_id into v_existing from public.kfc_pos_returns where idempotency_key = p_key;
  if found then return v_existing; end if;

  select * into v_session from public.kfc_pos_sessions where id = p_session for update;
  if not found or v_session.closed_at is not null then raise exception 'KFC_POS_CLOSED'; end if;

  if p_method is null or p_method not in ('cash', 'pin') then raise exception 'KFC_POS_BAD_REFUND_METHOD'; end if;
  if p_location is null or not exists (
    select 1 from public.kfc_locations where id = p_location and technician_id is null
  ) then raise exception 'KFC_POS_RETURN_LOCATION'; end if;

  -- Lock the original sale: concurrent returns of the same receipt queue here.
  select * into v_orig from public.sales_invoices where id = p_invoice for update;
  if not found or v_orig.pos_session_id is null or v_orig.pos_key is null or v_orig.credit_of_invoice_id is not null then
    raise exception 'KFC_POS_NO_RECEIPT';
  end if;

  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) = 0 or jsonb_array_length(p_lines) > 200 then
    raise exception 'KFC_POS_BAD_RETURN_LINES';
  end if;

  insert into public.sales_invoices (
    biller_name, biller_street, biller_postcode, biller_city, biller_email, biller_phone, biller_kvk, biller_btw, biller_iban,
    client_name, notes, subtotal, vat_total, total, status, paid_at, created_by, pos_session_id, pos_key, credit_of_invoice_id
  ) values (
    v_orig.biller_name, v_orig.biller_street, v_orig.biller_postcode, v_orig.biller_city, v_orig.biller_email,
    v_orig.biller_phone, v_orig.biller_kvk, v_orig.biller_btw, v_orig.biller_iban,
    v_orig.client_name, left('Kassaretour van ' || v_orig.invoice_number
      || coalesce(' · ' || nullif(btrim(coalesce(p_reason, '')), ''), ''), 500),
    0, 0, 0, 'betaald', now(), p_created_by, p_session, 'retour:' || p_key, p_invoice
  ) returning id, invoice_number into v_credit, v_number;

  insert into public.kfc_pos_returns (id, session_id, original_invoice_id, credit_invoice_id, method, refund_cents,
    location_id, reason, created_by, idempotency_key)
  values (v_return, p_session, p_invoice, v_credit, p_method, 0, p_location,
    left(nullif(btrim(coalesce(p_reason, '')), ''), 500), p_created_by, p_key);

  for v_req in select * from jsonb_array_elements(p_lines) loop
    v_i := v_i + 1;
    v_line_text := v_req->>'line_id';
    if v_line_text is null or v_line_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'KFC_POS_BAD_RETURN_LINES';
    end if;
    if v_line_text::uuid = any (v_seen) then raise exception 'KFC_POS_BAD_RETURN_LINES'; end if;
    v_seen := v_seen || v_line_text::uuid;
    if coalesce(v_req->>'quantity', '') !~ '^[0-9]{1,5}$' then raise exception 'KFC_POS_BAD_RETURN_LINES'; end if;
    v_qty := (v_req->>'quantity')::integer;
    if v_qty < 1 or v_qty > 10000 then raise exception 'KFC_POS_BAD_RETURN_LINES'; end if;

    select * into v_line from public.sales_invoice_lines where id = v_line_text::uuid and invoice_id = p_invoice;
    if not found then raise exception 'KFC_POS_BAD_RETURN_LINES'; end if;

    -- The stock move of the original sale line: which article, and at what cost it left.
    select * into v_sale_move from public.kfc_stock_moves
     where idempotency_key = v_orig.pos_key || ':line:' || v_line.line_no and reason = 'sale';
    if not found then raise exception 'KFC_POS_BAD_RETURN_LINES'; end if;

    v_sold := v_line.quantity::integer;
    select coalesce(sum(quantity), 0) into v_returned from public.kfc_pos_return_lines where invoice_line_id = v_line.id;
    if v_returned + v_qty > v_sold then raise exception 'KFC_POS_RETURN_EXCEEDS'; end if;

    -- Pro rata of what was paid for the line; the last return gets the remainder,
    -- so returning everything gives back exactly what was paid.
    v_line_incl := public.kfc_pos_line_incl(v_line);
    v_refund_line := round(v_line_incl::numeric * (v_returned + v_qty) / v_sold)::integer
                   - round(v_line_incl::numeric * v_returned / v_sold)::integer;
    v_unit_incl := coalesce(v_line.pos_unit_incl_cents, round(v_line.unit_price * (1 + v_line.vat_rate / 100) * 100)::integer);

    -- Negative line: quantity stays positive (sales_invoice_lines checks it), price and discount flip sign.
    insert into public.sales_invoice_lines (invoice_id, line_no, description, quantity, unit_price, discount, vat_rate,
      pos_unit_incl_cents, pos_discount_incl_cents)
    values (v_credit, v_i, left('Retour ' || v_line.description, 300), v_qty,
      -v_line.unit_price,
      -round(v_qty * v_line.unit_price - v_refund_line / (1 + v_line.vat_rate / 100) / 100.0, 2),
      v_line.vat_rate,
      -v_unit_incl,
      v_refund_line - v_qty * v_unit_incl);

    v_move := public.kfc_book_move(v_sale_move.article_code, p_location, v_qty, 'return', p_key || ':line:' || v_i,
      v_sale_move.unit_cost_cents, 'Kassa retour ' || v_number || ' (van ' || v_orig.invoice_number || ')',
      null, p_created_by, null, null, null, v_credit);

    insert into public.kfc_pos_return_lines (return_id, invoice_line_id, article_code, quantity, refund_cents, unit_cost_cents, stock_move_id)
    values (v_return, v_line.id, v_sale_move.article_code, v_qty, v_refund_line, v_sale_move.unit_cost_cents, v_move.id);

    v_total := v_total + v_refund_line;
    v_vat := v_vat + v_refund_line - v_refund_line / (1 + v_line.vat_rate / 100);
  end loop;

  -- Cash can only go out if the drawer should hold it.
  if p_method = 'cash' and v_total > 0 then
    select e.expected_cash_cents into v_drawer from public.kfc_pos_expected(p_session) e;
    if v_drawer < v_total then raise exception 'KFC_POS_CASH_SHORT'; end if;
  end if;

  update public.sales_invoices
     set total = -round(v_total / 100.0, 2), vat_total = -round(round(v_vat) / 100.0, 2),
         subtotal = -round((v_total - round(v_vat)) / 100.0, 2)
   where id = v_credit;
  update public.kfc_pos_returns set refund_cents = v_total where id = v_return;

  if v_total > 0 then
    insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, kind, created_by, idempotency_key)
    values (p_session, v_credit, p_method, -v_total, -v_total, 'refund', p_created_by, p_key || ':refund');
  end if;

  return v_credit;
exception when unique_violation then
  -- A parallel request with the same key won the race; everything above rolled back.
  select credit_invoice_id into v_existing from public.kfc_pos_returns where idempotency_key = p_key;
  if found then return v_existing; end if;
  raise;
end $$;

-- ---------------------------------------------------------------------------
-- Cash in / out
-- ---------------------------------------------------------------------------

create or replace function public.kfc_pos_cash_move(
  p_session uuid, p_key text, p_direction text, p_amount_cents integer, p_reason text, p_created_by uuid
) returns public.kfc_pos_cash_moves language plpgsql set search_path = public as $$
declare v_row public.kfc_pos_cash_moves; v_session public.kfc_pos_sessions; v_drawer integer;
begin
  if p_key is null or length(p_key) < 8 or length(p_key) > 80 then raise exception 'KFC_POS_BAD_KEY'; end if;
  select * into v_row from public.kfc_pos_cash_moves where idempotency_key = p_key;
  if found then return v_row; end if;

  select * into v_session from public.kfc_pos_sessions where id = p_session for update;
  if not found or v_session.closed_at is not null then raise exception 'KFC_POS_CLOSED'; end if;
  if p_direction is null or p_direction not in ('in', 'out') then raise exception 'KFC_POS_BAD_CASH_MOVE'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 or p_amount_cents > 10000000 then raise exception 'KFC_POS_BAD_CASH_MOVE'; end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then raise exception 'KFC_POS_REASON_REQUIRED'; end if;

  if p_direction = 'out' then
    select e.expected_cash_cents into v_drawer from public.kfc_pos_expected(p_session) e;
    if v_drawer < p_amount_cents then raise exception 'KFC_POS_CASH_SHORT'; end if;
  end if;

  insert into public.kfc_pos_cash_moves (session_id, direction, amount_cents, reason, created_by, idempotency_key)
  values (p_session, p_direction, p_amount_cents, left(btrim(p_reason), 500), p_created_by, p_key)
  returning * into v_row;
  return v_row;
exception when unique_violation then
  select * into v_row from public.kfc_pos_cash_moves where idempotency_key = p_key;
  if found then return v_row; end if;
  raise;
end $$;

-- ---------------------------------------------------------------------------
-- Close: count cash and PIN, number and freeze the Z-report
-- ---------------------------------------------------------------------------

-- The cash-only close of 0129 goes: a close must now include the PIN total.
drop function if exists public.kfc_pos_close(uuid, integer, text, uuid);

create or replace function public.kfc_pos_close(
  p_session uuid, p_counted_cents integer, p_counted_pin_cents integer, p_note text, p_closed_by uuid
) returns public.kfc_pos_sessions language plpgsql set search_path = public as $$
declare
  v_row public.kfc_pos_sessions; v_cash integer; v_pin integer; v_z integer; v_report jsonb; v_now timestamptz := now();
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if p_counted_cents is null or p_counted_cents < 0 or p_counted_cents > 100000000 then raise exception 'KFC_POS_BAD_COUNT'; end if;
  if p_counted_pin_cents is null or p_counted_pin_cents < 0 or p_counted_pin_cents > 100000000 then raise exception 'KFC_POS_BAD_PIN_COUNT'; end if;
  select * into v_row from public.kfc_pos_sessions where id = p_session for update;
  if not found then raise exception 'KFC_POS_NO_SESSION'; end if;
  if v_row.closed_at is not null then return v_row; end if;

  select e.expected_cash_cents, e.expected_pin_cents into v_cash, v_pin from public.kfc_pos_expected(p_session) e;

  -- Gapless: one closing at a time takes max + 1 inside this transaction.
  perform pg_advisory_xact_lock(hashtext('kfc_pos_z_number'));
  select coalesce(max(z_number), 0) + 1 into v_z from public.kfc_pos_sessions;

  with inv as (
    select i.id, i.credit_of_invoice_id, round(i.total * 100)::integer as total_cents
      from public.sales_invoices i where i.pos_session_id = p_session
  ), pay as (
    select p.method, p.kind, sum(p.amount_cents)::integer as cents
      from public.kfc_pos_payments p where p.session_id = p_session group by p.method, p.kind
  ), mv as (
    select m.direction, sum(m.amount_cents)::integer as cents, count(*)::integer as n
      from public.kfc_pos_cash_moves m where m.session_id = p_session group by m.direction
  ), vat as (
    select l.vat_rate, sum(public.kfc_pos_line_incl(l))::integer as incl
      from public.sales_invoice_lines l join inv on inv.id = l.invoice_id
     group by l.vat_rate
  )
  select jsonb_build_object(
    'z_number', v_z,
    'register', v_row.register,
    'opened_at', v_row.opened_at, 'opened_by', v_row.opened_by,
    'closed_at', v_now, 'closed_by', p_closed_by,
    'sales_count', (select count(*) from inv where credit_of_invoice_id is null),
    'sales_total_cents', coalesce((select sum(total_cents) from inv where credit_of_invoice_id is null), 0),
    'returns_count', (select count(*) from inv where credit_of_invoice_id is not null),
    'refunds_total_cents', coalesce(-(select sum(total_cents) from inv where credit_of_invoice_id is not null), 0),
    'net_total_cents', coalesce((select sum(total_cents) from inv), 0),
    'sales_by_method', jsonb_build_object(
      'cash',  coalesce((select cents from pay where method = 'cash'  and kind = 'sale'), 0),
      'pin',   coalesce((select cents from pay where method = 'pin'   and kind = 'sale'), 0),
      'other', coalesce((select cents from pay where method = 'other' and kind = 'sale'), 0)),
    'refunds_by_method', jsonb_build_object(
      'cash', coalesce(-(select cents from pay where method = 'cash' and kind = 'refund'), 0),
      'pin',  coalesce(-(select cents from pay where method = 'pin'  and kind = 'refund'), 0)),
    'cash_in_cents',  coalesce((select cents from mv where direction = 'in'), 0),
    'cash_in_count',  coalesce((select n from mv where direction = 'in'), 0),
    'cash_out_cents', coalesce((select cents from mv where direction = 'out'), 0),
    'cash_out_count', coalesce((select n from mv where direction = 'out'), 0),
    'vat', coalesce((select jsonb_agg(jsonb_build_object(
              'rate', vat_rate, 'incl_cents', incl,
              'base_cents', round(incl / (1 + vat_rate / 100))::integer,
              'vat_cents', incl - round(incl / (1 + vat_rate / 100))::integer) order by vat_rate desc) from vat), '[]'::jsonb),
    'opening_float_cents', v_row.opening_float_cents,
    'cash', jsonb_build_object('expected_cents', v_cash, 'counted_cents', p_counted_cents, 'difference_cents', p_counted_cents - v_cash),
    'pin',  jsonb_build_object('expected_cents', v_pin,  'counted_cents', p_counted_pin_cents, 'difference_cents', p_counted_pin_cents - v_pin),
    'note', v_note
  ) into v_report;

  update public.kfc_pos_sessions
     set closed_at = v_now, closed_by = p_closed_by,
         counted_cash_cents = p_counted_cents, expected_cash_cents = v_cash, cash_difference_cents = p_counted_cents - v_cash,
         counted_pin_cents = p_counted_pin_cents, expected_pin_cents = v_pin, pin_difference_cents = p_counted_pin_cents - v_pin,
         note = v_note, z_number = v_z, z_report = v_report
   where id = p_session
  returning * into v_row;
  return v_row;
end $$;

-- ---------------------------------------------------------------------------
-- Security: server-only, like 0129.
-- ---------------------------------------------------------------------------

alter table public.kfc_pos_cash_moves enable row level security;
alter table public.kfc_pos_returns enable row level security;
alter table public.kfc_pos_return_lines enable row level security;
revoke all on public.kfc_pos_cash_moves from public, anon, authenticated;
revoke all on public.kfc_pos_returns from public, anon, authenticated;
revoke all on public.kfc_pos_return_lines from public, anon, authenticated;
revoke all on sequence public.kfc_pos_cash_moves_id_seq from public, anon, authenticated;
revoke all on sequence public.kfc_pos_return_lines_id_seq from public, anon, authenticated;

revoke all on function public.kfc_pos_expected(uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_line_incl(public.sales_invoice_lines) from public, anon, authenticated;
revoke all on function public.kfc_pos_sale(uuid, text, jsonb, jsonb, uuid, text, jsonb, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_return(uuid, text, uuid, jsonb, text, uuid, text, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_cash_move(uuid, text, text, integer, text, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_close(uuid, integer, integer, text, uuid) from public, anon, authenticated;

-- ===== 0137_kfc_avg_cost.sql =====
-- ============================================================================
-- 0137: KeyForCars moving-average cost (gemiddelde kostprijs), ERPNext style.
--
-- Before this migration there was no valuation method: receipts and purchase
-- invoice lines overwrite kfc_articles.purchase_price_cents with the latest
-- price, stock was valued at quantity × that latest price, and a till sale
-- (0129) books its move without a cost, so the margin of an old sale changed
-- every time the purchase price changed.
--
-- What this adds
--   kfc_articles.avg_cost_cents            the article's moving average cost
--   kfc_stock_moves.avg_cost_after_cents   the average right after that move
--                                          (history for valuation on a date)
--   trigger kfc_stock_moves_avg_cost       BEFORE INSERT on kfc_stock_moves:
--                                          the whole mechanism. No existing RPC
--                                          is replaced, so every current and
--                                          future write path is covered.
--   0131 reports                           value stock at the average and cost
--                                          sales at the cost stamped on the move.
--
-- purchase_price_cents keeps its meaning "last purchase price" (reorder
-- proposals, supplier comparison, list margin). Nothing here writes it.
--
-- Behaviour per move reason. The reasons are exactly the values allowed by
-- kfc_stock_moves_reason_check (0090, widened in 0112): count, sale, return,
-- received, transfer, correction, issue, assembly. Writers found:
--   received   kfc_receive_po_line (0090/0110, PO line cost, may be null);
--              stock screen "receive" (src/lib/kfcInventory.ts, entered
--              total ÷ quantity, or null)
--   assembly   kfc_assemble (0112): parts −, cost = part's purchase price;
--              product +, cost = parts + labour (null when a part is unpriced)
--   return     kfc_return_line (0113) and the Woo return (0132): + at the
--              cost of the original sale moves; stock screen "return": null
--   sale       webshop shipment (0091/0124): cost = article's purchase price;
--              till kfc_pos_sale (0129): null; stock screen "sale": the
--              entered total ÷ quantity, else null
--   issue      job stock (0115/0124): cost = article's purchase price;
--              stock screen "issue": null
--   correction defect Woo return write-off (0132): − at the return's cost
--   transfer   kfc_transfer (0090, also van transfers 0124): both legs null
--   count      kfc_count_bin / kfc_bulk_count (0090/0092): null
--
--   on_hand = the article's quantity over ALL locations (quarantine and vans
--   included) before this move = sum(delta) of its earlier ledger rows. The
--   ledger is used, not kfc_stock_levels, because kfc_book_move and
--   kfc_count_bin update the level row before they insert the move.
--
--   | move                                         | unit cost on the move   | average                          |
--   |----------------------------------------------|-------------------------|----------------------------------|
--   | received / assembly / return, delta > 0,     | kept as given           | on_hand <= 0 or average unknown: |
--   |   cost given (an external cost)              |                         |   = cost; else (on_hand × avg +  |
--   |                                              |                         |   delta × cost)/(on_hand + delta)|
--   | received / assembly, delta > 0, no cost      | stays null (the real    | unchanged (units join at the     |
--   |   (PO line or entry without a price)         |   price is not known)   |   current average)               |
--   | return, delta > 0, no cost (stock screen)    | current average         | unchanged                        |
--   | any delta < 0 (sale, issue, assembly part,   | given cost kept; null   | unchanged                        |
--   |   correction, count, transfer out, …)        |   -> current average    |                                  |
--   | count / correction / transfer / sale / issue | given cost kept; null   | unchanged                        |
--   |   with delta > 0 (cost-neutral)              |   -> current average    |                                  |
--   | any move while the average is unknown        | null stays null (never  | unchanged (still unknown)        |
--   |                                              |   an invented zero)     |                                  |
--
--   "current average" on a move is rounded to whole cents (the column is an
--   integer); the average itself keeps four decimals.
--   NOTE: outbound callers that pass a cost keep it. The webshop shipment and
--   job issue functions pass the article's LAST PURCHASE PRICE, not the
--   average; that is their choice and is not overridden here (see docs).
--
-- Concurrency: the trigger locks the article row (FOR NO KEY UPDATE — the
-- strongest lock that does not block foreign-key checks of other tables) before
-- it reads the average and the ledger, so two receipts of the same article
-- serialise and neither update is lost. A replayed idempotency key fails on the
-- unique index after the trigger ran; kfc_book_move catches that inside its
-- exception block, which rolls the trigger's update back with it.
--
-- History: moves booked before this migration keep their (often null) cost.
-- Reports fall back to the average, then the purchase price, for those rows and
-- flag them as estimated. The average starts at the purchase price of the moment
-- of migration (backfill below), once.
--
-- Idempotent; server-only like 0090/0131.
-- ============================================================================

-- numeric(14,4), not integer cents: an average recomputed on every receipt and
-- rounded to whole cents each time drifts (a 0.5 ct rounding on each of many
-- small receipts accumulates); four decimals of a cent keep the drift far below
-- one cent, and numeric (not float) is exact decimal arithmetic. 10 digits
-- before the point = up to 99 999 999,99 euro per unit.
do $$
begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'kfc_articles' and column_name = 'avg_cost_cents') then
    alter table public.kfc_articles add column avg_cost_cents numeric(14,4);
    -- One-time backfill: the last purchase price is the best known cost today.
    update public.kfc_articles set avg_cost_cents = purchase_price_cents where purchase_price_cents is not null;
  end if;
end $$;
comment on column public.kfc_articles.avg_cost_cents is
  'Moving average cost in cents (4 decimals), maintained by trigger kfc_stock_moves_avg_cost (0137). Null = unknown.';
comment on column public.kfc_articles.purchase_price_cents is
  'Last purchase price in cents (receipt, purchase invoice, assembly). Not the valuation cost: see avg_cost_cents.';

alter table public.kfc_stock_moves add column if not exists avg_cost_after_cents numeric(14,4);
comment on column public.kfc_stock_moves.avg_cost_after_cents is
  'The article''s moving average cost right after this move (0137). Null on moves before 0137 or while unknown.';

create or replace function public.kfc_stock_moves_avg_cost()
returns trigger language plpgsql set search_path = public as $$
declare
  v_avg numeric(14,4);
  v_on_hand bigint;
begin
  -- Serialise every move of this article; the lock is held to commit.
  select avg_cost_cents into v_avg from public.kfc_articles where code = new.article_code for no key update;
  if not found then return new; end if;  -- the foreign key reports the unknown article

  if new.delta > 0 and new.reason in ('received', 'assembly', 'return') and new.unit_cost_cents is not null then
    -- Inbound at a known external cost: recompute the average.
    select coalesce(sum(delta), 0) into v_on_hand from public.kfc_stock_moves where article_code = new.article_code;
    if v_on_hand <= 0 or v_avg is null then
      v_avg := new.unit_cost_cents;
    else
      v_avg := round((v_on_hand * v_avg + new.delta::numeric * new.unit_cost_cents) / (v_on_hand + new.delta), 4);
    end if;
    update public.kfc_articles set avg_cost_cents = v_avg where code = new.article_code;
  elsif new.unit_cost_cents is null and v_avg is not null
        and not (new.delta > 0 and new.reason in ('received', 'assembly')) then
    -- Outbound or cost-neutral: stamp the current average, leave it unchanged.
    new.unit_cost_cents := round(v_avg)::integer;
  end if;

  new.avg_cost_after_cents := v_avg;
  return new;
end $$;

drop trigger if exists kfc_stock_moves_avg_cost on public.kfc_stock_moves;
create trigger kfc_stock_moves_avg_cost before insert on public.kfc_stock_moves
  for each row execute function public.kfc_stock_moves_avg_cost();

-- ---------------------------------------------------------------------------
-- Reports (0131). Same columns, order and types; new columns only at the end.
-- ---------------------------------------------------------------------------

-- Sales lines: cost = the cost stamped on the move. Moves without one (booked
-- before 0137, or while the average was unknown) fall back to the average, then
-- the purchase price, flagged cost_estimated as before. New: cost_source.
create or replace view public.kfc_sales_lines as
select
  m.id                                                   as move_id,
  m.created_at,
  (m.created_at at time zone 'Europe/Amsterdam')::date   as day,
  m.article_code,
  a.name,
  a.sku,
  a.category,
  m.reason,
  -m.delta                                               as quantity,  -- sale +, return −
  case
    when m.order_line_id is not null then 'webshop'
    when m.sales_invoice_id is not null and coalesce(m.note, '') like 'Kassa %' then 'kassa'
    when m.sales_invoice_id is not null then 'factuur'
    else 'overig'
  end                                                    as channel,
  so.shop,
  coalesce(so.number, si.invoice_number)                 as document,
  m.order_line_id,
  m.sales_invoice_id,
  case
    when sl.id is not null and sl.quantity > 0
      then round(coalesce(sl.total_excl_cents, 0)::numeric * (-m.delta) / sl.quantity)::bigint
    when il.unit_price is not null
      then round((il.unit_price * il.quantity - il.discount) / il.quantity * 100 * (-m.delta))::bigint
    else round(coalesce(a.sale_price_cents, 0)::numeric / 1.21 * (-m.delta))::bigint
  end                                                    as revenue_cents,
  (sl.id is null and il.unit_price is null)              as revenue_estimated,
  round(coalesce(m.unit_cost_cents::numeric, a.avg_cost_cents, a.purchase_price_cents::numeric, 0) * (-m.delta))::bigint
                                                         as cost_cents,
  (m.unit_cost_cents is null)                            as cost_estimated,
  case
    when m.unit_cost_cents is not null then 'boeking'
    when a.avg_cost_cents is not null then 'gemiddeld'
    when a.purchase_price_cents is not null then 'inkoopprijs'
  end                                                    as cost_source
from public.kfc_stock_moves m
join public.kfc_articles a on a.code = m.article_code
left join public.kfc_shop_order_lines sl on sl.id = m.order_line_id
left join public.kfc_shop_orders so on so.id = sl.order_id
left join public.sales_invoices si on si.id = m.sales_invoice_id
left join lateral (
  select l.unit_price, l.quantity, l.discount
  from public.sales_invoice_lines l
  where m.sales_invoice_id is not null and l.invoice_id = m.sales_invoice_id
    and l.description in (a.name, left(a.name || case when a.sku <> '' then ' (' || a.sku || ')' else '' end, 300))
  order by l.line_no
  limit 1
) il on true
where m.reason in ('sale', 'return');

-- Article overview: stock value at the average (purchase price only when no
-- average is known: value_estimated). margin_pct stays the list margin on the
-- last purchase price. New: avg_cost_cents, value_estimated.
create or replace view public.kfc_article_overview as
with levels as (
  select l.article_code,
         sum(l.minimum) filter (where loc.kind = 'shelf')                                   as minimum,
         array_agg(distinct loc.warehouse) filter (where l.quantity <> 0)                   as warehouses,
         array_agg(distinct loc.warehouse || '/' || loc.shelf || '/' || loc.box)
           filter (where l.quantity <> 0)                                                    as locations,
         max(l.last_counted_at)                                                              as last_counted_at
  from public.kfc_stock_levels l
  join public.kfc_locations loc on loc.id = l.location_id
  group by l.article_code
), moves as (
  select article_code,
         max(created_at) filter (where reason in ('received', 'assembly') and delta > 0) as last_received_at,
         max(created_at) filter (where reason = 'sale')                                  as last_sold_at,
         max(created_at)                                                                  as last_move_at,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '30 days'), 0)  as sold_30d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '90 days'), 0)  as sold_90d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '365 days'), 0) as sold_365d
  from public.kfc_stock_moves
  group by article_code
), suppliers as (
  select pl.article_code,
         array_agg(distinct po.supplier)                                                   as suppliers,
         (array_agg(po.supplier order by coalesce(po.ordered_at, po.created_at) desc))[1]  as last_supplier,
         (array_agg(pl.unit_cost_cents order by coalesce(po.ordered_at, po.created_at) desc)
            filter (where pl.unit_cost_cents is not null))[1]                              as last_po_cost_cents
  from public.kfc_purchase_order_lines pl
  join public.kfc_purchase_orders po on po.id = pl.po_id
  where po.status <> 'cancelled'
  group by pl.article_code
)
select
  a.code, a.name, a.sku, a.ean, a.category, a.status, a.condition, a.tracking, a.supplier_ref,
  a.sale_price_cents, a.purchase_price_cents, a.photo_version, a.created_at, a.updated_at,
  p.physical, p.unusable, p.reserved, p.available, p.incoming,
  coalesce(lv.minimum, 0)::integer                                                   as minimum,
  round(greatest(p.physical - p.unusable, 0) * coalesce(a.avg_cost_cents, a.purchase_price_cents::numeric, 0))::bigint
                                                                                     as stock_value_cents,
  (a.avg_cost_cents is null and a.purchase_price_cents is null)                      as unpriced,
  coalesce(lv.warehouses, '{}')                                                      as warehouses,
  coalesce(lv.locations, '{}')                                                       as locations,
  lv.last_counted_at,
  coalesce(s.suppliers, '{}')                                                        as suppliers,
  s.last_supplier,
  s.last_po_cost_cents,
  mv.last_received_at, mv.last_sold_at, mv.last_move_at,
  coalesce(mv.sold_30d, 0)::integer  as sold_30d,
  coalesce(mv.sold_90d, 0)::integer  as sold_90d,
  coalesce(mv.sold_365d, 0)::integer as sold_365d,
  case
    when p.physical < 0 then 'negatief'
    when p.physical = 0 then 'nul'
    when coalesce(lv.minimum, 0) > 0 and p.available <= lv.minimum then 'laag'
    else 'op_voorraad'
  end as stock_state,
  case when a.sale_price_cents is null or a.purchase_price_cents is null or a.sale_price_cents = 0 then null
       else round((a.sale_price_cents / 1.21 - a.purchase_price_cents) / (a.sale_price_cents / 1.21) * 100, 1)
  end as margin_pct,
  a.avg_cost_cents,
  (a.avg_cost_cents is null)                                                         as value_estimated
from public.kfc_articles a
join public.kfc_stock_position p on p.article_code = a.code
left join levels lv on lv.article_code = a.code
left join moves mv on mv.article_code = a.code
left join suppliers s on s.article_code = a.code;

-- Valuation on a date: the average as it was after the article's last move up
-- to that day (avg_cost_after_cents). An article without any move since 0137 has
-- had the same average since the backfill, so its current average is used.
-- Before 0137 (no recorded average yet): the last receipt / assembly cost up to
-- that day, then the purchase price — both flagged cost_estimated, as in 0131.
create or replace function public.kfc_stock_valuation(p_date date, p_warehouse text default '', p_category text default '')
returns table (
  article_code text, name text, sku text, category text,
  location_id uuid, warehouse text, shelf text, box text, kind text, technician_id uuid,
  quantity bigint, unit_cost_cents integer, value_cents bigint, cost_estimated boolean
) language sql stable set search_path = '' as $$
  with bound as (select (p_date + 1)::timestamp at time zone 'Europe/Amsterdam' as ends),
  qty as (
    select m.article_code, m.location_id, sum(m.delta)::bigint as quantity
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends
    group by m.article_code, m.location_id
    having sum(m.delta) <> 0
  ), avg_on as (
    select distinct on (m.article_code) m.article_code, m.avg_cost_after_cents
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends and m.avg_cost_after_cents is not null
    order by m.article_code, m.created_at desc, m.id desc
  ), cost as (
    select distinct on (m.article_code) m.article_code, m.unit_cost_cents
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends and m.delta > 0 and m.reason in ('received', 'assembly')
      and m.unit_cost_cents is not null
    order by m.article_code, m.created_at desc, m.id desc
  ), priced as (
    select q.*, a.name, a.sku, a.category,
      coalesce(
        av.avg_cost_after_cents,
        case when not exists (select 1 from public.kfc_stock_moves x
                               where x.article_code = q.article_code and x.avg_cost_after_cents is not null)
             then a.avg_cost_cents end
      ) as avg_cost,
      c.unit_cost_cents as receipt_cost, a.purchase_price_cents
    from qty q
    join public.kfc_articles a on a.code = q.article_code
    left join avg_on av on av.article_code = q.article_code
    left join cost c on c.article_code = q.article_code
    where (p_category = '' or a.category = p_category)
  )
  select pr.article_code, pr.name, pr.sku, pr.category,
    pr.location_id, coalesce(loc.warehouse, '(geen locatie)'), loc.shelf, loc.box, coalesce(loc.kind, 'shelf'), loc.technician_id,
    pr.quantity,
    coalesce(round(pr.avg_cost)::integer, pr.receipt_cost, pr.purchase_price_cents),
    case when coalesce(loc.kind, 'shelf') = 'quarantine' then 0::bigint
         else round(greatest(pr.quantity, 0) * coalesce(pr.avg_cost, pr.receipt_cost::numeric, pr.purchase_price_cents::numeric, 0))::bigint end,
    pr.avg_cost is null
  from priced pr
  left join public.kfc_locations loc on loc.id = pr.location_id
  where (p_warehouse = '' or coalesce(loc.warehouse, '(geen locatie)') = p_warehouse);
$$;

-- Ledger: value = the move's own cost; without one the average, then the
-- purchase price (only moves from before 0137 or with an unknown average).
create or replace function public.kfc_stock_ledger(
  p_from date, p_to date, p_article text default '', p_reason text default '', p_warehouse text default '',
  p_query text default '', p_page integer default 1, p_page_size integer default 100
) returns jsonb language sql stable set search_path = '' as $$
  with bounds as (
    select p_from::timestamp at time zone 'Europe/Amsterdam' as starts,
           (p_to + 1)::timestamp at time zone 'Europe/Amsterdam' as ends
  ), arts as (
    select a.code, a.name, a.sku, a.category, a.purchase_price_cents, a.avg_cost_cents from public.kfc_articles a
    where (p_article = '' or a.code = p_article)
      and (p_query = '' or strpos(lower(a.code), lower(p_query)) > 0 or strpos(lower(a.name), lower(p_query)) > 0
           or strpos(lower(a.sku), lower(p_query)) > 0)
  ), running as (
    select m.id, m.created_at, m.article_code, m.location_id, m.delta, m.quantity_after, m.reason,
      m.unit_cost_cents, m.note, m.order_line_id, m.sales_invoice_id, m.purchase_order_line_id, m.count_batch_id, m.created_by,
      sum(m.delta) over (partition by m.article_code order by m.created_at, m.id) as balance
    from public.kfc_stock_moves m
    join arts on arts.code = m.article_code
    cross join bounds
    where m.created_at < bounds.ends
  ), period as (
    select r.*, arts.name, arts.sku, arts.category,
      loc.warehouse, loc.shelf, loc.box,
      round(coalesce(r.unit_cost_cents::numeric, arts.avg_cost_cents, arts.purchase_price_cents::numeric) * r.delta)::bigint as value_cents,
      po.supplier, so.number as order_number, si.invoice_number
    from running r
    join arts on arts.code = r.article_code
    cross join bounds
    left join public.kfc_locations loc on loc.id = r.location_id
    left join public.kfc_purchase_order_lines pl on pl.id = r.purchase_order_line_id
    left join public.kfc_purchase_orders po on po.id = pl.po_id
    left join public.kfc_shop_order_lines sl on sl.id = r.order_line_id
    left join public.kfc_shop_orders so on so.id = sl.order_id
    left join public.sales_invoices si on si.id = r.sales_invoice_id
    where r.created_at >= bounds.starts
      and (p_reason = '' or r.reason = p_reason)
      and (p_warehouse = '' or loc.warehouse = p_warehouse)
  ), opening as (
    select coalesce(sum(m.delta), 0) as qty
    from public.kfc_stock_moves m join arts on arts.code = m.article_code cross join bounds
    where m.created_at < bounds.starts
  ), totals as (
    select count(*) as n,
      coalesce(sum(delta) filter (where delta > 0), 0) as incoming,
      coalesce(-sum(delta) filter (where delta < 0), 0) as outgoing
    from period
  )
  select jsonb_build_object(
    'opening', (select qty from opening),
    'count', totals.n, 'incoming', totals.incoming, 'outgoing', totals.outgoing,
    'rows', coalesce((
      select jsonb_agg(to_jsonb(v) order by v.created_at desc, v.id desc) from (
        select * from period order by created_at desc, id desc
        limit case when p_page_size <= 0 then 50000 else p_page_size end
        offset case when p_page_size <= 0 then 0 else (greatest(p_page, 1)::bigint - 1) * p_page_size end
      ) v), '[]'::jsonb)
  ) from totals;
$$;

-- Ageing: value at the average (purchase price when unknown). Buckets unchanged.
create or replace function public.kfc_stock_ageing(p_category text default '')
returns table (
  code text, name text, sku text, category text, physical integer, unit_cost_cents integer, value_cents bigint,
  q_0_30 bigint, q_31_60 bigint, q_61_90 bigint, q_91_180 bigint, q_181_365 bigint, q_365p bigint,
  oldest_days integer, avg_days numeric, last_received_at timestamptz, last_sold_at timestamptz
) language sql stable set search_path = '' as $$
  with stock as (
    select o.code, o.name, o.sku, o.category, o.physical, o.purchase_price_cents, o.avg_cost_cents, o.last_received_at, o.last_sold_at
    from public.kfc_article_overview o
    where o.physical > 0 and (p_category = '' or o.category = p_category)
  ), inbound as (
    select m.article_code, m.created_at, m.delta,
      sum(m.delta) over (partition by m.article_code order by m.created_at desc, m.id desc) as cum
    from public.kfc_stock_moves m
    join stock s on s.code = m.article_code
    where m.delta > 0 and m.reason <> 'transfer'
  ), alloc as (
    select i.article_code,
      greatest(0, least(i.delta, s.physical - (i.cum - i.delta)))::bigint as qty,
      (now() at time zone 'Europe/Amsterdam')::date - (i.created_at at time zone 'Europe/Amsterdam')::date as age
    from inbound i join stock s on s.code = i.article_code
  ), known as (
    select article_code,
      sum(qty) as qty,
      sum(qty) filter (where age <= 30) as a30, sum(qty) filter (where age between 31 and 60) as a60,
      sum(qty) filter (where age between 61 and 90) as a90, sum(qty) filter (where age between 91 and 180) as a180,
      sum(qty) filter (where age between 181 and 365) as a365, sum(qty) filter (where age > 365) as a365p,
      max(age) filter (where qty > 0) as oldest,
      sum(qty * age) as weighted
    from alloc group by article_code
  )
  select s.code, s.name, s.sku, s.category, s.physical::integer,
    coalesce(round(s.avg_cost_cents)::integer, s.purchase_price_cents),
    round(s.physical * coalesce(s.avg_cost_cents, s.purchase_price_cents::numeric, 0))::bigint,
    coalesce(k.a30, 0)::bigint, coalesce(k.a60, 0)::bigint, coalesce(k.a90, 0)::bigint,
    coalesce(k.a180, 0)::bigint, coalesce(k.a365, 0)::bigint,
    (coalesce(k.a365p, 0) + greatest(s.physical - coalesce(k.qty, 0), 0))::bigint,
    case when s.physical > coalesce(k.qty, 0) then null else k.oldest end::integer,
    case when coalesce(k.qty, 0) = 0 then null else round(k.weighted::numeric / k.qty, 0) end,
    s.last_received_at, s.last_sold_at
  from stock s left join known k on k.article_code = s.code;
$$;

-- kfc_sales_report, kfc_article_movement and kfc_article_totals read the views
-- above and need no change.

-- Security ---------------------------------------------------------------------
revoke all on function public.kfc_stock_moves_avg_cost() from public, anon, authenticated;
revoke all on public.kfc_sales_lines from public, anon, authenticated;
revoke all on public.kfc_article_overview from public, anon, authenticated;
grant select on public.kfc_sales_lines to service_role;
grant select on public.kfc_article_overview to service_role;
revoke all on function public.kfc_stock_valuation(date, text, text) from public, anon, authenticated;
revoke all on function public.kfc_stock_ledger(date, date, text, text, text, text, integer, integer) from public, anon, authenticated;
revoke all on function public.kfc_stock_ageing(text) from public, anon, authenticated;
grant execute on function public.kfc_stock_valuation(date, text, text) to service_role;
grant execute on function public.kfc_stock_ledger(date, date, text, text, text, text, integer, integer) to service_role;
grant execute on function public.kfc_stock_ageing(text) to service_role;

-- ===== 0138_kfc_ship_rule.sql =====
-- ============================================================================
-- 0138: the ship rule lives in the database, not only behind a disabled button.
--
--   kfc_ship_order(order, key, by)  same signature, same void return, same
--     idempotency (a shipped order returns at once, before any check, so a
--     replay still answers like the first call), same KFC_NO_ORDER /
--     KFC_NOT_PAID / KFC_STOCK_RESERVED_FOR_JOB behaviour. New:
--
--   1. KFC_NOT_PICKED unless every line that has to leave the warehouse is
--      fully reserved and picked. "Has to leave the warehouse" is exactly the
--      set of lines the 0124 version booked a sale for: state <> 'cancelled',
--      quantity > 0, article_code not null. Such a line passes only with
--      state = 'picked', reserved >= quantity and picked >= quantity
--      (kfc_pick_line sets picked = reserved; reserved can exceed quantity
--      when the shop lowered the quantity after the allocator filled it).
--      Unmapped lines (article_code null) are still marked shipped without a
--      move; zero-quantity lines are still left alone. Both never block.
--      The check runs after the order row and its lines are locked, so two
--      ship calls queue on the order row and the second one returns early
--      on fulfilment = 'shipped'; a pick or an import cannot change a line
--      between the check and the bookings.
--
--   2. No negative stock from shipping. The 0124 version booked the whole
--      quantity on the single fullest bin, which kfc_book_move allows to go
--      below zero for 'sale'. Now the quantity is taken from central shelf
--      bins (no van, no quarantine) that hold stock, fullest first, never
--      more than a bin holds. An article without any bin keeps the unlocated
--      booking, but only up to the unlocated balance. If that is not enough:
--      KFC_CENTRAL_STOCK_REQUIRED (the existing code and message), and the
--      whole call rolls back. The first bin keeps the 0124 idempotency key
--      (key:line); further bins get key:line:2, key:line:3, ...
--      The line can never ship more than was reserved for it, because the
--      rule above already requires reserved >= quantity.
--
-- Lock order stays order row -> lines -> stock level rows -> article advisory
-- lock (taken by the move trigger), like kfc_pick_line and kfc_count_bin.
--
-- kfc_book_move and kfc_allocate are not touched. Idempotent.
-- ============================================================================

create or replace function public.kfc_ship_order(p_order uuid, p_key text, p_created_by uuid default null)
returns void
language plpgsql
set search_path = public
as $$
declare
  v_order public.kfc_shop_orders; v_line record; v_bin record; v_cost integer;
  v_left integer; v_take integer; v_n integer; v_unlocated bigint;
begin
  select * into v_order from public.kfc_shop_orders where id = p_order for update;
  if not found then raise exception 'KFC_NO_ORDER'; end if;
  if v_order.fulfilment = 'shipped' then return; end if;
  if v_order.status <> 'processing' then raise exception 'KFC_NOT_PAID'; end if;

  -- The ship rule, checked under the order lock with the lines locked too.
  perform 1 from public.kfc_shop_order_lines where order_id = p_order order by id for update;
  if exists (
    select 1 from public.kfc_shop_order_lines
     where order_id = p_order and state <> 'cancelled' and quantity > 0 and article_code is not null
       and not (state = 'picked' and reserved >= quantity and picked >= quantity)
  ) then
    raise exception 'KFC_NOT_PICKED';
  end if;

  for v_line in select * from public.kfc_shop_order_lines where order_id = p_order and state <> 'cancelled' and quantity > 0 order by id loop
    if v_line.article_code is null then
      update public.kfc_shop_order_lines set state = 'shipped' where id = v_line.id;
      continue;
    end if;
    if v_line.reserved > 0 then
      insert into public.kfc_reservations (article_code, order_line_id, delta) values (v_line.article_code, v_line.id, -v_line.reserved);
    end if;
    select purchase_price_cents into v_cost from public.kfc_articles where code = v_line.article_code;

    -- Lock every central shelf bin of the article in a fixed order, then read
    -- the quantities fresh and take from the fullest first.
    perform 1 from public.kfc_stock_levels l join public.kfc_locations loc on loc.id = l.location_id
     where l.article_code = v_line.article_code and loc.technician_id is null and loc.kind = 'shelf'
     order by l.location_id for update of l;
    v_left := v_line.quantity; v_n := 0;
    for v_bin in
      select l.location_id, l.quantity
        from public.kfc_stock_levels l join public.kfc_locations loc on loc.id = l.location_id
       where l.article_code = v_line.article_code and loc.technician_id is null and loc.kind = 'shelf' and l.quantity > 0
       order by l.quantity desc, l.location_id
    loop
      exit when v_left <= 0;
      v_take := least(v_left, v_bin.quantity);
      v_n := v_n + 1;
      perform public.kfc_book_move(v_line.article_code, v_bin.location_id, -v_take, 'sale',
        p_key || ':' || v_line.id::text || case when v_n = 1 then '' else ':' || v_n::text end,
        v_cost, null, null, p_created_by, v_line.id);
      v_left := v_left - v_take;
    end loop;

    if v_left > 0 then
      -- Not enough on the central shelves. Unlocated stock only counts for an
      -- article that has no bin at all (kfc_book_move refuses it otherwise).
      if v_n > 0 or exists (select 1 from public.kfc_stock_levels where article_code = v_line.article_code) then
        raise exception 'KFC_CENTRAL_STOCK_REQUIRED';
      end if;
      perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || v_line.article_code));
      select coalesce(sum(delta), 0) into v_unlocated
        from public.kfc_stock_moves where article_code = v_line.article_code and location_id is null;
      if v_unlocated < v_left then raise exception 'KFC_CENTRAL_STOCK_REQUIRED'; end if;
      perform public.kfc_book_move(v_line.article_code, null, -v_left, 'sale', p_key || ':' || v_line.id::text,
        v_cost, null, null, p_created_by, v_line.id);
    end if;

    update public.kfc_shop_order_lines set reserved = 0, picked = quantity, state = 'shipped' where id = v_line.id;
  end loop;
  update public.kfc_shop_orders set fulfilment = 'shipped', shipped_at = now(), shipped_by = p_created_by where id = p_order;
end $$;

revoke all on function public.kfc_ship_order(uuid, text, uuid) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.kfc_ship_order(uuid, text, uuid) to service_role;
  end if;
end $$;

notify pgrst, 'reload schema';

-- ===== 0139_kfc_po_close.sql =====
-- 0139: close an ordered purchase order short ("rest komt niet").
--
-- Problem: an ordered purchase order whose supplier delivers less than ordered
-- could never be finished. Only a draft could be cancelled, so the undelivered
-- rest stayed "incoming" forever: expected stock was overstated, real shortages
-- were hidden in the reorder proposal and the order stayed in every open list.
--
-- What this adds:
--   * status 'closed' on kfc_purchase_orders, with closed_at, closed_by and a
--     mandatory close_reason. Lines keep their ordered and received quantities;
--     nothing is deleted or rewritten, so the history stays true.
--   * kfc_close_purchase_order(p_po, p_reason, p_user): only from 'ordered',
--     locks the order row, works with part of the goods received or none at all
--     (the supplier cancelled). Refuses an order whose lines are all received
--     (KFC_PO_FULLY_RECEIVED: that order becomes 'received' on its last receipt,
--     as kfc_receive_po_line has always done). A replay on an already closed
--     order returns quietly. Codes: KFC_PO_REASON_REQUIRED, KFC_PO_NOT_FOUND,
--     KFC_PO_NOT_ORDERED, KFC_PO_FULLY_RECEIVED.
--   * kfc_receive_po_line refuses a closed order like a cancelled one
--     (KFC_PO_CLOSED next to 0110's KFC_PO_CANCELLED). It now also locks the
--     order row before the status check, so a receipt and a close on the same
--     order are serialised (line lock first, then order lock; the close only
--     locks the order, so there is no lock-order inversion).
--
-- Checked for the undelivered rest (incoming / open value / reorder / expected):
--   kfc_stock_position (0090, latest 0115)   incoming: status = 'ordered'  -> no change
--   kfc_webshop_position (0124)              reads kfc_stock_position       -> no change
--   kfc_article_overview (0131)              incoming from kfc_stock_position; its
--                                            suppliers CTE (last supplier / last PO cost)
--                                            uses status <> 'cancelled': a closed order
--                                            was a real purchase, so it stays -> no change
--   kfc_article_totals (0131)                counts incoming > 0 from the overview -> no change
--   kfc_product_master (0134)                reads kfc_stock_position       -> no change
--   kfc_woo stock sync (0132)                reads available, not incoming   -> no change
--   kfc_supplier_balance (0130)              open_pos: draft/ordered; late_pos and
--                                            on_order_cents: ordered        -> no change
--   kfc_purchase_line_facts (0130)           open_quantity was quantity - received for
--                                            every status                   -> CHANGED:
--                                            0 for a closed order (same columns)
--   kfc_receive_with_photo (0127)            refuses status <> 'ordered' (KFC_RECEIPT_CONFLICT)
--                                            -> no change, a closed order is refused there
--   kfc_stock_movement_report (0119), kfc_stock_ledger (0131): "incoming" there is
--                                            booked moves, not open orders -> no change
-- App side: the reorder proposal (voorraad) uses kfc_stock_position.incoming; the
-- owner dashboard reads only draft/ordered orders.

set search_path = public;

-- ---------------------------------------------------------------------------
-- Columns and status
-- ---------------------------------------------------------------------------
alter table public.kfc_purchase_orders add column if not exists closed_at    timestamptz;
alter table public.kfc_purchase_orders add column if not exists closed_by    uuid;
alter table public.kfc_purchase_orders add column if not exists close_reason text;

-- The status check was created inline in 0090, so its name is generated. Find
-- every check constraint on exactly the status column, drop it, add ours.
do $$
declare
  v_attnum smallint;
  r record;
begin
  select attnum into v_attnum from pg_attribute
   where attrelid = 'public.kfc_purchase_orders'::regclass and attname = 'status' and not attisdropped;
  for r in
    select conname from pg_constraint
     where conrelid = 'public.kfc_purchase_orders'::regclass and contype = 'c' and conkey = array[v_attnum]
  loop
    execute format('alter table public.kfc_purchase_orders drop constraint %I', r.conname);
  end loop;
  alter table public.kfc_purchase_orders add constraint kfc_purchase_orders_status_check
    check (status in ('draft', 'ordered', 'received', 'cancelled', 'closed'));

  if not exists (select 1 from pg_constraint where conname = 'kfc_purchase_orders_closed_fields'
                   and conrelid = 'public.kfc_purchase_orders'::regclass) then
    alter table public.kfc_purchase_orders add constraint kfc_purchase_orders_closed_fields
      check (status <> 'closed' or (closed_at is not null and close_reason is not null and length(btrim(close_reason)) between 1 and 500));
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Closing
-- ---------------------------------------------------------------------------
create or replace function public.kfc_close_purchase_order(p_po uuid, p_reason text, p_user uuid)
returns public.kfc_purchase_orders language plpgsql set search_path = '' as $$
declare
  v_po public.kfc_purchase_orders;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if v_reason = '' or length(v_reason) > 500 then raise exception 'KFC_PO_REASON_REQUIRED'; end if;
  select * into v_po from public.kfc_purchase_orders where id = p_po for update;
  if not found then raise exception 'KFC_PO_NOT_FOUND'; end if;
  if v_po.status = 'closed' then return v_po; end if;          -- replay: quiet
  if v_po.status <> 'ordered' then raise exception 'KFC_PO_NOT_ORDERED'; end if;
  -- Read after the order lock: a receipt that got the lock first is visible here.
  if not exists (select 1 from public.kfc_purchase_order_lines where po_id = p_po and received < quantity) then
    raise exception 'KFC_PO_FULLY_RECEIVED';
  end if;
  update public.kfc_purchase_orders
     set status = 'closed', closed_at = now(), closed_by = p_user, close_reason = v_reason
   where id = p_po
  returning * into v_po;
  return v_po;
end $$;

revoke all on function public.kfc_close_purchase_order(uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.kfc_close_purchase_order(uuid, text, uuid) to service_role;

-- ---------------------------------------------------------------------------
-- Receiving: refuse a closed order like a cancelled one (body as 0110 plus the
-- order lock and the 'closed' branch).
-- ---------------------------------------------------------------------------
create or replace function public.kfc_receive_po_line(
  p_line uuid, p_quantity integer, p_location uuid, p_key text, p_created_by uuid default null
) returns public.kfc_stock_moves language plpgsql as $$
declare v_line public.kfc_purchase_order_lines; v_row public.kfc_stock_moves; v_open integer; v_status text;
begin
  if p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  select * into v_line from public.kfc_purchase_order_lines where id = p_line for update;
  if not found then raise exception 'KFC_NO_PO_LINE'; end if;
  if exists (select 1 from public.kfc_stock_moves where idempotency_key = p_key) then
    select * into v_row from public.kfc_stock_moves where idempotency_key = p_key; return v_row;
  end if;
  select status into v_status from public.kfc_purchase_orders where id = v_line.po_id for update;
  if v_status = 'cancelled' then
    raise exception 'KFC_PO_CANCELLED';
  end if;
  if v_status = 'closed' then
    raise exception 'KFC_PO_CLOSED';
  end if;
  v_row := public.kfc_book_move(v_line.article_code, p_location, p_quantity, 'received', p_key,
    v_line.unit_cost_cents, null, null, p_created_by, null, p_line);
  update public.kfc_purchase_order_lines set received = received + p_quantity where id = p_line;
  if v_line.unit_cost_cents is not null then
    update public.kfc_articles set purchase_price_cents = v_line.unit_cost_cents, updated_at = now() where code = v_line.article_code;
  end if;
  select count(*) into v_open from public.kfc_purchase_order_lines where po_id = v_line.po_id and received < quantity;
  if v_open = 0 then
    update public.kfc_purchase_orders set status = 'received', received_at = now() where id = v_line.po_id and status = 'ordered';
  end if;
  return v_row;
end $$;

revoke all on function public.kfc_receive_po_line(uuid, integer, uuid, text, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Reports: the rest of a closed order is no longer open (same columns as 0130).
-- ---------------------------------------------------------------------------
create or replace view public.kfc_purchase_line_facts as
select l.id as line_id, o.id as po_id, o.status, o.supplier_id, coalesce(s.name, o.supplier) as supplier_name,
       o.created_at, o.ordered_at, o.expected_on, o.received_at, o.invoice_ref,
       (coalesce(o.ordered_at, o.created_at) at time zone 'Europe/Amsterdam')::date as order_date,
       l.article_code, a.name as article_name, a.sku, a.category,
       l.quantity, l.received,
       case when o.status = 'closed' then 0 else greatest(l.quantity - l.received, 0) end as open_quantity,
       l.unit_cost_cents,
       l.quantity::bigint * l.unit_cost_cents as ordered_cents,
       l.received::bigint * l.unit_cost_cents as received_cents,
       (select max(m.created_at) from public.kfc_stock_moves m where m.purchase_order_line_id = l.id and m.reason = 'received') as last_receipt_at
  from public.kfc_purchase_order_lines l
  join public.kfc_purchase_orders o on o.id = l.po_id
  left join public.kfc_articles a on a.code = l.article_code
  left join public.kfc_suppliers s on s.id = o.supplier_id;

revoke all on public.kfc_purchase_line_facts from public, anon, authenticated;
grant select on public.kfc_purchase_line_facts to service_role;

-- ===== 0140_kfc_period_lock.sql =====
-- ============================================================================
-- 0140: period lock ("afgesloten periode") for the KeyForCars books.
--
--   kfc_period_lock      the current lock: at most one row (id is the constant
--                        true). No row = nothing is locked.
--   kfc_period_lock_log  append-only history of every change: old date, new
--                        date, who, when, note.
--   kfc_set_period_lock(p_until, p_user, p_note)
--                        set, move or remove the lock. The date must lie before
--                        today in Europe/Amsterdam (the shop is still trading
--                        today). Moving the lock back (reopening) or removing it
--                        (p_until null) needs a note. Serialised by an advisory
--                        lock; every change is logged; the same date twice is a
--                        no-op and is not logged.
--   kfc_period_lock_state()  current lock + last 20 log rows, for the screen.
--
-- Enforcement is by triggers, so the posting functions (0093/0094/0095/0129/
-- 0130/0090) stay untouched. Each trigger raises KFC_PERIOD_LOCKED when the
-- row's business date is on or before locked_until:
--   kfc_customer_ledger, kfc_supplier_ledger   entry_date
--   kfc_stock_moves                            created_at as an Amsterdam date
--
-- What is blocked, and why not more:
--   INSERT  always checked. Reversals (kfc_reverse_entry, kfc_reverse_supplier_
--           entry) insert a new row dated today, so reversing a locked-period
--           entry still works. kfc_book_move never takes a created_at from the
--           caller (always now()), so on stock moves this is a safety net.
--   DELETE  always checked.
--   UPDATE  only when a money or date column changes (ledgers: amount_cents,
--           vat_cents, entry_date, entry_type; stock moves: delta,
--           unit_cost_cents, created_at). Other updates are legitimate today
--           and must keep working on old rows: 0112 sets assembly_id on moves,
--           and the foreign keys "on delete set null" (sales_invoice_id,
--           purchase_order_id) update old rows when an invoice or order is
--           deleted. The triggers are declared "update of <those columns>", so
--           such updates do not even fire them.
--   TRUNCATE refused on the three tables while a lock exists.
--
-- With no lock row each trigger does one primary-key read of an empty table and
-- returns, so an install that never sets a lock (Autosleutel24) is unaffected.
-- Server-only like the other kfc_ tables. Idempotent.
-- ============================================================================
set search_path = public;

create table if not exists public.kfc_period_lock (
  id            boolean primary key default true check (id),
  locked_until  date not null,
  set_by        uuid,
  set_at        timestamptz not null default now(),
  note          text
);

create table if not exists public.kfc_period_lock_log (
  id         bigserial primary key,
  old_until  date,
  new_until  date,
  set_by     uuid,
  set_at     timestamptz not null default now(),
  note       text
);
create index if not exists kfc_period_lock_log_time_idx on public.kfc_period_lock_log (set_at desc, id desc);

-- The history is append-only.
create or replace function public.kfc_period_lock_log_guard() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  raise exception 'kfc_period_lock_log is append-only';
end $$;
drop trigger if exists kfc_period_lock_log_guard on public.kfc_period_lock_log;
create trigger kfc_period_lock_log_guard before update or delete on public.kfc_period_lock_log
  for each row execute function public.kfc_period_lock_log_guard();
drop trigger if exists kfc_period_lock_log_no_truncate on public.kfc_period_lock_log;
create trigger kfc_period_lock_log_no_truncate before truncate on public.kfc_period_lock_log
  for each statement execute function public.kfc_period_lock_log_guard();

-- ---------------------------------------------------------------------------
-- Set / move / remove
-- ---------------------------------------------------------------------------
create or replace function public.kfc_set_period_lock(p_until date, p_user uuid, p_note text default null)
returns date language plpgsql set search_path = public, pg_temp as $$
declare
  v_today date := (now() at time zone 'Europe/Amsterdam')::date;
  v_old   date;
  v_note  text := nullif(btrim(coalesce(p_note, '')), '');
begin
  perform pg_advisory_xact_lock(hashtext('kfc_period_lock'));
  select locked_until into v_old from public.kfc_period_lock where id for update;

  if p_until is not null and p_until >= v_today then raise exception 'KFC_PERIOD_FUTURE'; end if;
  if p_until is not distinct from v_old then return v_old; end if;
  -- Reopening (moving back) or removing the lock needs a reason.
  if (p_until is null or (v_old is not null and p_until < v_old)) and v_note is null then
    raise exception 'KFC_PERIOD_NOTE_REQUIRED';
  end if;

  if p_until is null then
    delete from public.kfc_period_lock where id;
  else
    insert into public.kfc_period_lock (id, locked_until, set_by, set_at, note)
    values (true, p_until, p_user, now(), v_note)
    on conflict (id) do update set locked_until = excluded.locked_until, set_by = excluded.set_by,
                                   set_at = excluded.set_at, note = excluded.note;
  end if;
  insert into public.kfc_period_lock_log (old_until, new_until, set_by, note) values (v_old, p_until, p_user, v_note);
  return p_until;
end $$;

-- Current lock and the last 20 changes, for the settings screen.
create or replace function public.kfc_period_lock_state() returns jsonb
language sql stable set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'lock', (select to_jsonb(l) - 'id' from public.kfc_period_lock l where l.id),
    'log',  coalesce((select jsonb_agg(to_jsonb(g) order by g.set_at desc, g.id desc)
                        from (select * from public.kfc_period_lock_log order by set_at desc, id desc limit 20) g), '[]'::jsonb)
  );
$$;

-- ---------------------------------------------------------------------------
-- Enforcement
-- ---------------------------------------------------------------------------
create or replace function public.kfc_period_lock_guard() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_until date; v_old date; v_new date;
begin
  select locked_until into v_until from public.kfc_period_lock where id;
  if v_until is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_table_name = 'kfc_stock_moves' then
    if tg_op <> 'INSERT' then v_old := (old.created_at at time zone 'Europe/Amsterdam')::date; end if;
    if tg_op <> 'DELETE' then v_new := (new.created_at at time zone 'Europe/Amsterdam')::date; end if;
    if tg_op = 'UPDATE' and (old.delta, old.unit_cost_cents, old.created_at)
                            is not distinct from (new.delta, new.unit_cost_cents, new.created_at) then
      return new;
    end if;
  else
    if tg_op <> 'INSERT' then v_old := old.entry_date; end if;
    if tg_op <> 'DELETE' then v_new := new.entry_date; end if;
    if tg_op = 'UPDATE' and (old.amount_cents, old.vat_cents, old.entry_date, old.entry_type)
                            is not distinct from (new.amount_cents, new.vat_cents, new.entry_date, new.entry_type) then
      return new;
    end if;
  end if;

  if v_old <= v_until or v_new <= v_until then
    raise exception 'KFC_PERIOD_LOCKED'
      using detail = format('%s: boekdatum %s, afgesloten t/m %s', tg_table_name, coalesce(v_new, v_old), v_until);
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

create or replace function public.kfc_period_lock_no_truncate() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if exists (select 1 from public.kfc_period_lock where id) then raise exception 'KFC_PERIOD_LOCKED'; end if;
  return null;
end $$;

drop trigger if exists kfc_customer_ledger_period_lock on public.kfc_customer_ledger;
create trigger kfc_customer_ledger_period_lock
  before insert or delete or update of amount_cents, vat_cents, entry_date, entry_type on public.kfc_customer_ledger
  for each row execute function public.kfc_period_lock_guard();

drop trigger if exists kfc_supplier_ledger_period_lock on public.kfc_supplier_ledger;
create trigger kfc_supplier_ledger_period_lock
  before insert or delete or update of amount_cents, vat_cents, entry_date, entry_type on public.kfc_supplier_ledger
  for each row execute function public.kfc_period_lock_guard();

drop trigger if exists kfc_stock_moves_period_lock on public.kfc_stock_moves;
create trigger kfc_stock_moves_period_lock
  before insert or delete or update of delta, unit_cost_cents, created_at on public.kfc_stock_moves
  for each row execute function public.kfc_period_lock_guard();

drop trigger if exists kfc_customer_ledger_period_lock_truncate on public.kfc_customer_ledger;
create trigger kfc_customer_ledger_period_lock_truncate before truncate on public.kfc_customer_ledger
  for each statement execute function public.kfc_period_lock_no_truncate();
drop trigger if exists kfc_supplier_ledger_period_lock_truncate on public.kfc_supplier_ledger;
create trigger kfc_supplier_ledger_period_lock_truncate before truncate on public.kfc_supplier_ledger
  for each statement execute function public.kfc_period_lock_no_truncate();
drop trigger if exists kfc_stock_moves_period_lock_truncate on public.kfc_stock_moves;
create trigger kfc_stock_moves_period_lock_truncate before truncate on public.kfc_stock_moves
  for each statement execute function public.kfc_period_lock_no_truncate();

-- ---------------------------------------------------------------------------
-- Server only
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['kfc_period_lock', 'kfc_period_lock_log'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;
grant usage, select on sequence public.kfc_period_lock_log_id_seq to service_role;
revoke all on function public.kfc_set_period_lock(date, uuid, text) from public, anon, authenticated;
revoke all on function public.kfc_period_lock_state() from public, anon, authenticated;
revoke all on function public.kfc_period_lock_guard() from public, anon, authenticated;
revoke all on function public.kfc_period_lock_no_truncate() from public, anon, authenticated;
revoke all on function public.kfc_period_lock_log_guard() from public, anon, authenticated;
grant execute on function public.kfc_set_period_lock(date, uuid, text) to service_role;
grant execute on function public.kfc_period_lock_state() to service_role;

notify pgrst, 'reload schema';

-- ===== 0141_ad_conversion_matches.sql =====
/*
 * Sales matched to an ad click, confirmed by a person, before Google sees them.
 *
 * Numbered 0141 (written as 0109 on branch claude/ads-conversion-upload, which
 * clashed with 0109_my_open_offers). Run after 0140. Additive and idempotent: one new table, its indexes and its
 * policy. Paste it into the Supabase SQL editor; safe to run twice.
 *
 * Why. Until now the daily Google Ads file (/api/ads/conversions.csv) decided
 * by itself which finished job belonged to which click, including matches no
 * person had looked at (a WhatsApp code, a phone number). A wrong click id
 * teaches Smart Bidding to buy the wrong traffic, so from this migration on
 * the file carries only rows from this table: a sale (finished job, WhatsApp
 * win, or a WhatsApp ad review marked "gedaan") plus the one click a person
 * confirmed for it on /admin/conversies. The matcher only proposes.
 *
 * Money. Both amounts are stored and labelled: value_incl_btw is what the
 * customer paid, value_excl_btw is that amount without 21% BTW and is the
 * figure uploaded to Google. Prices in this business are incl. BTW unless a
 * chat says otherwise (owner, 21 Nov 2026); vat_assumed marks that case.
 *
 * Nothing personal is stored here: a source id, a click id, times, amounts.
 */
create table if not exists public.ad_conversion_matches (
  id              uuid primary key default gen_random_uuid(),
  created_at      timestamptz not null default now(),

  /* What was sold. source_id points into jobs, whatsapp_quotes or whatsapp_ad_reviews. */
  source          text not null check (source in ('job', 'whatsapp_quote', 'whatsapp_review')),
  source_id       uuid not null,

  /* The click, exactly as Google gave it. */
  click_kind      text not null check (click_kind in ('gclid', 'gbraid', 'wbraid')),
  click_id        text not null check (click_id ~ '^[A-Za-z0-9_-]{8,200}$'),
  clicked_at      timestamptz not null,
  /* The evidence that tied them: own_click, lead_form, office_claim, chat_code, quote_code, review_code, same_phone, time. */
  rule            text not null,

  decision        text not null check (decision in ('bevestigd', 'afgewezen')),
  conversion_at   timestamptz,
  value_incl_btw  numeric(10,2),
  value_excl_btw  numeric(10,2),
  vat_assumed     boolean not null default false,

  decided_by      uuid references auth.users (id) on delete set null,
  decided_at      timestamptz not null default now(),
  /* First time Google's scheduled fetch received this row. Informational. */
  uploaded_at     timestamptz,

  constraint ad_conversion_matches_confirmed_complete check (
    decision <> 'bevestigd'
    or (conversion_at is not null and conversion_at >= clicked_at
        and value_incl_btw > 0 and value_excl_btw > 0 and value_excl_btw <= value_incl_btw)
  )
);

comment on table public.ad_conversion_matches is
  'Sale-to-ad-click matches decided by the office on /admin/conversies. Only bevestigd rows go to Google Ads (value_excl_btw). No personal data.';

/* One decision per sale and click: deciding again replaces it. */
create unique index if not exists ad_conversion_matches_pair_key
  on public.ad_conversion_matches (source, source_id, click_id);

/* A sale is uploaded once, with one click. */
create unique index if not exists ad_conversion_matches_one_per_sale
  on public.ad_conversion_matches (source, source_id)
  where decision = 'bevestigd';

/* A click earns one sale. */
create unique index if not exists ad_conversion_matches_one_per_click
  on public.ad_conversion_matches (click_id)
  where decision = 'bevestigd';

alter table public.ad_conversion_matches enable row level security;

revoke all on public.ad_conversion_matches from anon;
grant select, insert, update, delete on public.ad_conversion_matches to authenticated;

do $$
begin
  if not exists (select 1 from pg_policies where tablename = 'ad_conversion_matches' and policyname = 'ad_conversion_matches_office') then
    create policy ad_conversion_matches_office on public.ad_conversion_matches
      for all
      using (public.crm_role() in ('owner', 'kantoor'))
      with check (public.crm_role() in ('owner', 'kantoor'));
  end if;
end $$;

notify pgrst, 'reload schema';

